INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('nature', 'extral', 'extral', 'Extral / Humain galactique', NULL, '{"nature":"extral","description":"Talass, Mo’sen, Baséanh, Rocréens et Thalsios appartiennent à des civilisations galactiques dont l’implantation terrestre est récente et très diverse. S’y ajoutent des cas rares comme les Ad’rak et les Humains galactiques de l’AIDH, dont certains programmes produisent les exceptionnels Homo Superior. Une espèce ou un profil biologique ne détermine jamais automatiquement le réseau, la doctrine ou l’équipement du personnage.","carte":"**EXTRAL · NATURE** — gratuit\n\n- **Voilé** : l''Hologramme te traduit en humain. Aucun bonus. Tes besoins biologiques restent les tiens : air, humidité, nourriture, soins adaptés.\n- **Semi-Révélé / Révélé** : selon ton profil (cartes ci-dessous).\n- **Physiologie n''est pas économie d''action** : une anatomie inhabituelle ne donne ni PA, ni attaque, ni Défense active, ni Réaction en plus, sauf texte explicite.\n- **Faiblesse** : aucune malédiction. Ce qui te met en danger, c''est ce que le Voile ne supprime pas : un milieu hostile, un organe vital exposé, une infrastructure qui lâche.\n\n### Cartes de profil (gratuites, une seule)\n\n**TALASS** — petits êtres segmentaires, technique, méfiance de la violence\n- SR : +1 Esprit. R : +2 Esprit, +1 Agilité.\n- Anatomie segmentaire : ton corps est fait de segments. Le segment vital (le tronc) ne se détache jamais ; les segments périphériques (membres) peuvent être perdus puis récupérés ou réattachés.\n- Bond talass : bonds sans élan et changements d''appui, dans les limites de ton endurance.\n- Adhérence naturelle : tu t''accroches aux surfaces comme ton espèce ; descriptif, sans bonus chiffré.\n- Soie conductrice : ta soie transporte un courant ou un Talwa compatible.\n- Affinité Talwa''Etax : substrat psychique ; ses usages contrôlés passent par la voie du Talwa.\n- Perception des fractures : tu détectes une fracture dimensionnelle active ou un résidu récent du Néant (présence, pas sa nature).\n\n**MO''SEN** — reptiloïdes cuirassés, Mosenine, sens prédateurs\n- SR : +1 Vigueur. R : +2 Vigueur, +1 Agilité.\n- Cuirasse mo''senne : Armure corporelle 1, cumulable avec une armure portée compatible.\n- Griffes et dentition : Pugilat DGT 2.\n- Digestion absolue : tu digères ce qui rendrait un humain malade ; descriptif. Ce n''est pas une immunité (le chiffre est dans Digestion sélective).\n- Thermotolérance : tu supportes des écarts de température qui gênent un humain ; descriptif.\n\n**BASÉANH** — quatre bras, six yeux, laboratoire vivant\n- SR : +1 Volonté. R : +1 Esprit, +1 Volonté, +1 Charisme.\n- Tardollas : deux préparations actives à la fois. Une préparation demande un échantillon ou une matière biologique, des nutriments et environ 30 minutes (un test si la culture est complexe). Employée, elle est consommée.\n- Quatre bras : aucun PA, attaque, Défense ou Réaction en plus.\n- Immunité adaptative : +3 contre maladies, poisons, toxines et contamination biologique.\n- Stabilité manuelle : descriptif (le chiffre est dans Ancrage manuel).\n\n**ROCRÉEN** — molluscoïdes amphibies, Noyau, banc psychique\n- SR : +1 Charisme. R : +2 Charisme, +1 Esprit.\n- Amphibie : tu respires dans l''air et sous l''eau, sans pénalité parce que tu combats ou te déplaces immergé.\n- Noyau rocréen : centre de ta régénération. Une attaque ciblée sur le Noyau, une fois celui-ci identifié, peut sur une Altération appropriée suspendre ta régénération jusqu''à la fin de la scène.\n- Quadrimanie rocréenne : quatre membres tentaculaires. Ton mucus te fixe aux surfaces : tu grimpes sur des surfaces très difficiles à saisir.\n- Résonance psychique : communication et perceptions partagées avec les télépathes compatibles proches.\n\n**THALSIOS** — amphibioïdes massifs, mains précises, travail concret\n- SR : +1 Volonté. R : +2 Volonté, +1 Vigueur.\n- Amphibie thalsios : tu développes ou atrophies tes branchies en quelques minutes ; immergé, tu tiens presque indéfiniment dans une eau respirable.\n- Charpente cartilagineuse : +3 contre fracture, bris osseux ou trauma squelettique.\n- Toucher thalsios : tu perçois vibrations et variations de pression. Acclimaté à la Terre, tu sens les fluctuations locales de l''Hologramme, sans identification.\n\n**HOMO SUPERIOR** — origine rare, réservée aux Humains de l''AIDH\n- SR : +1 Vigueur. R : +1 Vigueur, +1 Agilité, +1 Volonté. Tu restes humain dans tous tes états.\n- Essaim nanitique : population nanitique intégrée, substrat de tes talents ; pas un équipement.\n- Homéostasie assistée : tu connais ton état physiologique général, pas sa cause.\n- Hémostase nanitique : un Saignement ordinaire s''arrête à la fin du round ; ni soin ni Stabilisation.\n- Organisme optimisé : +3 pour résister aux effets d''un environnement naturel hostile.\n- Métabolisme de campagne : quelques jours de sommeil réduit et de repas irréguliers sans pénalité notable.\n- Patchs tatoués : supports de liaison de ton équipement (voie Patchs tatoués).\n\n**AD''RAK** — origine restreinte : réfugiés, dissidents, communautés libres\n- SR : +1 Vigueur. R : +3 Vigueur. Un loyaliste de l''Armée noire n''est pas un personnage ordinaire.\n- Gabarit ad''rak (R) : environ 2,60 m (hommes) ou 2,20 m (femmes). Véhicules, mobilier, passages et armures posent de vraies contraintes. Une arme humaine à deux mains se manie souvent à une main, sans attaque en plus.\n- Force ad''rak : tu tentes des efforts hors échelle humaine ; pas de jet quand l''issue est certaine.\n- Pugilat ad''rak : SR DGT 2, R DGT 3.\n- Compatibilité terrestre : respiration, eau et alimentation proches de l''humain.\n\n**Changements** : Perception des fractures ajoutée au profil talass (absente du tableau du site). Anatomie segmentaire, Tardollas, Amphibie, Amphibie thalsios et Noyau rocréen reçoivent un texte tiré du talent lui-même, du livre V6 (préparations) ou du Bestiaire (Amphibie, Noyau vital). Digestion absolue, Thermotolérance, Adhérence et Stabilité manuelle restent descriptives : aucune source ne leur donne de chiffre. Les deux Amphibie restent distincts (l''un respire partout, l''autre change de branchies). Ventouses (#45) rejoint Quadrimanie rocréenne, qui était vide.\n\n---","traits_gratuits":[],"droits_acquis":"Les talents achetés avant les voies restent acquis ; les règles de voie valent pour les achats suivants (décision 20)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'extral', 'extral_talass', 'Talass', NULL, '{"nature":"extral","chemin":["Talass"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_talass_cinetique_segmentaire', 'Cinétique segmentaire', NULL, '{"nature":"extral","forme":"deux_portes","forme_lot":"2 portes","verrou":"ordre_paliers","portes":{"A":"Rebonds","B":"Corps segmentaire"},"identite":null,"profil":null,"changements":"Trajectoire : « attaques anticipant cette trajectoire » précisé en « attaques à distance ». Détachement : la fréquence 1/scène de la colonne du site passe dans le texte ; la phrase « menottes… par magie » part en lore. Zéro-G garde son coût du site (1 ; le JSON dit 2)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-rebond-d-appui', 'Rebond d''appui', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"R","activation":"Passif","texte_court":"en R, tu enchaînes les rebonds sans reprendre d''élan : +3 en Athlétisme pour les bonds difficiles sur les surfaces autour de toi. Ta distance de Déplacement ne change pas.","texte_reference":"Vous enchaînez les rebonds sans nouvel élan et gagnez +3 aux tests d’Athlétisme pour des bonds difficiles utilisant les surfaces environnantes. La distance normale, les appuis réels et les limites d’endurance demeurent.","lore":"Le Talass traite chaque surface solide comme une occasion de rediriger son mouvement. Mur, plafond ou mobilier devient un appui fugace qui casse la trajectoire sans exiger un nouvel élan.","groupe_actuel":"Talass › Voie I — Cinétique segmentaire — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-trajectoire-impossible', 'Trajectoire impossible', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","activation":"Lors d’un Déplacement","texte_court":"en R, pendant un Déplacement par rebonds, murs, plafonds et franchissements ordinaires ne coûtent ni PA ni test. Jusqu''à ta prochaine activation, les attaques à distance contre toi subissent −3. Rien en terrain entièrement ouvert.","texte_reference":"Lors d’un Déplacement par rebonds, les murs, plafonds et franchissements ordinaires accessibles ne demandent ni PA supplémentaire ni test d’Athlétisme. Jusqu’au début de votre prochaine activation, les attaques anticipant cette trajectoire subissent −3 ; des appuis réels restent nécessaires.\n\nDes surfaces réelles permettent les rebonds ; ce talent ne fonctionne pas dans un espace entièrement ouvert.","lore":"Une pièce pleine d’obstacles devient un réseau de vecteurs pour le Talass. Bonds et appuis s’enchaînent si vite que prévoir sa position suivante devient plus difficile que simplement le suivre des yeux.","groupe_actuel":"Talass › Voie I — Cinétique segmentaire — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-zero-g-natif', 'Zéro-G natif', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R","activation":"Passif","texte_court":"en R, apesanteur, faible gravité et repères changeants ne te gênent pas. Il te faut une surface pour t''accrocher et te propulser.","texte_reference":"Vous ignorez les difficultés dues à l’apesanteur, à une faible gravité ou à des repères changeants. Une surface accessible reste nécessaire pour vous accrocher et vous propulser.","lore":"Pour un Talass, l’apesanteur n’est pas une perte de repères mais un environnement normal. Tant qu’un support existe, il se fixe puis se propulse avec la même assurance qu’une créature terrestre marche sur son sol.","groupe_actuel":"Talass › Voie I — Cinétique segmentaire — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-detachement-reflexe', 'Détachement réflexe', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R","activation":"Réaction — 1/Scène","texte_court":"en R, réaction 1/scène : quand un segment périphérique est saisi, coincé, attaché ou happé, tu le détaches et te libères aussitôt. Aucun dégât, mais le segment est perdu jusqu''à ce qu''il soit récupéré, remplacé ou réattaché. Jamais le segment vital.","texte_reference":"Lorsqu''un segment périphérique est : saisi ; coincé ; attaché ; happé par un mécanisme le Talass peut volontairement le détacher. Il se libère immédiatement de cette contrainte précise. Le détachement ne provoque aucun dégât supplémentaire, mais : le segment est réellement perdu jusqu''à ce qu''il soit récupéré, remplacé ou réattaché. Un Talass qui abandonne sa main pour échapper à des menottes n''a plus cette main cinq secondes plus tard par magie. Le Talent ne fonctionne jamais sur le segment vital.","lore":"Un segment Talass peut être abandonné plutôt que devenir le point par lequel tout le corps est capturé. La perte est réelle, mais la liberté immédiate vaut parfois davantage qu’un membre périphérique récupérable plus tard.","groupe_actuel":"Talass › Voie I — Cinétique segmentaire — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_talass_trame_de_soie', 'Trame de soie', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Relais avant Réseau (le réseau suppose le fil). Vision des fractures sort de cette voie (voie Fractures). Phrases de limite en double retirées."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-trame-sensible', 'Trame sensible', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":"Préparation — quelques minutes","texte_court":"en R, après quelques minutes, tu tends une toile de 10 m de rayon au plus. Tant que tu y restes relié, tu localises à peu près toute perturbation, sans savoir qui la cause.","texte_reference":"Après quelques minutes de préparation, surveillez une trame couvrant au maximum 10 m de rayon tant que vous y restez physiquement relié. Vous localisez approximativement les perturbations, sans identifier leur auteur.","lore":"La soie fine devient un organe étendu tant que le Talass y reste relié. Toute traction ou rupture significative revient jusqu’à lui comme une vibration localisable sans révéler ce qui a touché le fil.","groupe_actuel":"Talass › Voie II — Trame de soie — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-relais-conducteur', 'Relais conducteur', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"R","activation":"Selon l’effet conduit","texte_court":"en R, un fil continu porte un effet du Talwa jusqu''à 30 m ; l''électricité, des données ou un contact magique approprié peuvent aussi l''emprunter si l''effet l''accepte. PA, puissance et protections restent ceux de l''effet.","texte_reference":"Un fil de soie continu permet d’exercer un effet compatible du Talwa à son extrémité jusqu’à 30 m. Les PA, la puissance et les protections restent ceux de l’effet ; les autres conductions réellement compatibles restent possibles.\n\nÉlectricité, données et contact magique approprié peuvent emprunter la soie si l’effet accepte réellement cette conduction. Un effet absent n’est jamais acquis.","lore":"La soie Talass peut transporter ce qui accepte vraiment la conduction : charge, données, Talwa ou contact magique approprié. Le fil ne crée aucune puissance ; il déplace simplement le point où elle peut passer.","groupe_actuel":"Talass › Voie II — Trame de soie — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-reseau-de-soie', 'Réseau de soie', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R","activation":"Préparation — réseau physique","texte_court":"en R, tu prépares jusqu''à cinq nœuds dans 10 m, chacun relié par 30 m de fil au plus. Un effet conduit part d''un nœud au choix, un par activation, sans attaque ni zone en plus.","texte_reference":"Vous pouvez préparer cinq nœuds de soie dans une zone de 10 m de rayon, chacun relié par un trajet de fil de 30 m maximum. Vos effets compatibles partent d’un seul nœud choisi par activation, sans attaque ou zone d’effet supplémentaire.","lore":"Une trame relie plusieurs nœuds du même espace et transforme la zone en petit réseau physique. Capteurs, signaux et Talwa peuvent y circuler comme s’ils partageaient une même architecture câblée.","groupe_actuel":"Talass › Voie II — Trame de soie — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_talass_talwa_etax', 'Talwa''Etax', NULL, '{"nature":"extral","forme":"deux_portes","forme_lot":"2 portes","verrou":"ordre_paliers","portes":{"A":"Sonder","B":"Relier"},"identite":null,"profil":null,"changements":"Champ entropique **3 → 2 PTV** (changement de règle : il ne fait que prolonger le scan, verdict « sous-évalué » du rapport). Doublon de limites retiré."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-projection-du-talwa', 'Projection du Talwa', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"SR/R","activation":"Actif — 1 PA","texte_court":"en SR/R, 1 PA : tu perçois grossièrement une pièce ou environ 10 m : volumes, masses, obstacles, êtres en mouvement. Tu ne reconnais personne et ne lis aucune pensée.","texte_reference":"Le Talass projette brièvement son sens psychique autour de lui. Dans une pièce ou environ 10 mètres, il obtient une perception grossière : volumes ; masses ; obstacles ; êtres en mouvement. Il ne reconnaît pas automatiquement les individus et ne lit aucune pensée. Les barrières dimensionnelles véritables bloquent le scan.","lore":"Le Talass étend brièvement sa perception psychique à la pièce. Masses, volumes et mouvements apparaissent comme un relief grossier, assez pour comprendre l’espace mais trop pauvre pour lire des pensées ou reconnaître chaque individu.","groupe_actuel":"Talass › Voie III — Talwa’Etax — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-champ-entropique', 'Champ entropique', NULL, '{"nature":"extral","cout":2,"cout_actuel":3,"palier":"II","porte":"A","palier_double":null,"acces":"SR/R","activation":"Actif — 1 PA après le scan","texte_court":"après une Projection, 1 PA : la veille tient toute la scène sans entretien. Chaque déplacement significatif te donne une position approximative, jamais l''identité, la Nature ou l''intention. Une créature immobile t''échappe.","texte_reference":"Après le scan, 1 PA maintient pour la scène une veille psychique de la zone de 10 m, sans entretien supplémentaire. Les déplacements significatifs donnent une position approximative, jamais l’identité ni les intentions ; les véritables barrières dimensionnelles bloquent la veille.\n\nUne créature parfaitement immobile ne produit pas de déplacement significatif. La veille n’identifie ni individu, ni Nature, ni intention.","lore":"Après avoir projeté son Talwa, le Talass garde une empreinte psychique du volume exploré. Un déplacement important qui traverse cette empreinte trouble le champ et révèle direction et position approximatives.","groupe_actuel":"Talass › Voie III — Talwa’Etax — 7 PTV","statut_regle":"correction","changements":"Coût 3 → 2. Champ entropique **3 → 2 PTV** (changement de règle : il ne fait que prolonger le scan, verdict « sous-évalué » du rapport). Doublon de limites retiré."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-lien-talwa', 'Lien Talwa', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"SR/R","activation":"Actif — 1 PA","texte_court":"en SR/R, 1 PA : tu échanges mots et images simples avec une cible consentante à 20 m, pour la scène. Aucune fouille de pensée.","texte_reference":"Pour 1 PA, communiquez volontairement par mots et images simples avec une cible consentante à 20 m maximum, pour la scène. Aucune fouille de pensée ni lecture forcée des sens.","lore":"Le Talwa peut devenir fil mental entre deux êtres proches. Pensées formulées, images simples et impressions élémentaires circulent volontairement sans ouvrir pour autant l’ensemble de l’esprit de l’un à l’autre.","groupe_actuel":"Talass › Voie III — Talwa’Etax — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-main-du-talwa', 'Main du Talwa', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"SR/R","activation":"Actif — 1 PA par manipulation","texte_court":"en SR/R, 1 PA par manipulation : tu agis sur un objet de 5 kg au plus à 10 m. Une tâche fine demande son test. Ni étranglement, ni projection de créature, ni projectile offensif.","texte_reference":"Pour 1 PA par manipulation, agissez sur un objet de 5 kg maximum situé à 10 m dans votre Talwa. Une tâche fine utilise le test approprié ; pas d’étranglement, de projection d’une créature ou de projectile offensif implicite.","lore":"Le Talwa saisit un petit objet à distance comme une main légère sans doigts visibles. Il pousse, tourne ou actionne ce que sa puissance permet, sans transformer la télékinésie en arme absolue contre les corps.","groupe_actuel":"Talass › Voie III — Talwa’Etax — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_talass_fractures', 'Fractures', NULL, '{"nature":"extral","forme":"progression","forme_lot":"progression courte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"note de développement retirée (« Clarifier en même temps le trait gratuit… ») ; le trait est désormais sur la carte."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-vision-des-fractures', 'Vision des fractures', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Passif","texte_court":"en SR/R, tu distingues une fracture active d''un résidu et gagnes +3 pour estimer son âge, sa stabilité ou son danger d''après les indices. Ni destination ni responsable sans indices.","texte_reference":"Vous distinguez une fracture dimensionnelle active d’un résidu et gagnez +3 pour en estimer l’ancienneté, la stabilité ou le danger à partir des indices perceptibles. La détection élémentaire reste innée ; ni destination ni responsable ne sont révélés sans indices.\n\nClarifier en même temps le trait gratuit, actuellement trop abrégé ; ne pas retirer au Talass la perception que sa biologie décrit.","lore":"Les Talass sentent certaines blessures de l’espace comme d’autres sentent une odeur de brûlé. Brèche dimensionnelle, résidu de Néant ou continuité troublée indiquent que le lieu n’est plus parfaitement normal, sans expliquer pourquoi.","groupe_actuel":"Talass › Voie II — Trame de soie — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'extral', 'extral_mo_sen', 'Mo''sen', NULL, '{"nature":"extral","chemin":["Mo''sen"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_mo_sen_mosenine', 'Mosenine', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Réflexe de chasse **1/round → 1/scène** (texte du livre V6) : une Défense active gratuite chaque round contredisait la létalité. Surpuissance : **scène → fin du round, 1/scène** (livre V6). La note « renforcement de durée proposé » n''est pas appliquée. Crête : le contrecoup du livre V6 est rétabli. C''est le ressort mo''sen face à Surcadence (Homo Superior) et Déchaînement (Ad''rak)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-poussee-hormonale', 'Poussée hormonale', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":"1/Scène","texte_court":"en R, 1/scène : +3 à un test de Vigueur, d''Agilité, d''Athlétisme ou de combat physique, annoncé avant le jet.","texte_reference":"Avant un test reposant directement sur : Vigueur ; Agilité ; Athlétisme ; combat physique le Mo''sen libère brutalement de la Mosenine. Le test bénéficie d''une : circonstance favorable +3.","lore":"Avant l’effort, le Mo’sen déclenche une décharge endocrinienne calibrée pour ce geste précis. Force, vitesse ou coordination bénéficient de cette montée sans modifier durablement son organisme.","groupe_actuel":"Mo’sen › Voie I — Mosenine — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-surpuissance', 'Surpuissance', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"R","activation":"Actif — 1 PA — scène","texte_court":"en R, 1 PA, 1/scène : jusqu''à la fin du round, ta Vigueur compte +2 pour les efforts de force et les prises. Ni PV ni dégâts.","texte_reference":"Pour 1 PA, comptez votre Vigueur comme supérieure de 2 pour les efforts de force et les luttes de prise pendant la scène. Ni PV, dégâts ni autres valeurs dérivées ne sont augmentés.\n\nRenforcement de durée proposé : à confronter au caractère explosif de la Mosenine en fiction, sans rendre toutes ses techniques durables.","lore":"La Mosenine peut détourner tout le corps vers l’effort de force brute. Pendant quelques secondes, chaque groupe musculaire sert à pousser, retenir ou arracher, sans transformer cette surcharge en réserve de vie ou en dégâts supplémentaires.","groupe_actuel":"Mo’sen › Voie I — Mosenine — 8 PTV","statut_regle":"correction","changements":"Réflexe de chasse **1/round → 1/scène** (texte du livre V6) : une Défense active gratuite chaque round contredisait la létalité. Surpuissance : **scène → fin du round, 1/scène** (livre V6). La note « renforcement de durée proposé » n''est pas appliquée. Crête : le contrecoup du livre V6 est rétabli. C''est le ressort mo''sen face à Surcadence (Homo Superior) et Déchaînement (Ad''rak)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-reflexe-de-chasse', 'Réflexe de chasse', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R","activation":"Réaction gratuite — 1/round","texte_court":"en R, 1/scène : attaqué sans être Surpris, tu fais une Défense active physique sans payer de PA.","texte_reference":"Une fois par round, effectuez une Défense active physique sans PA. Le talent seul ne permet pas cette défense en Surprise, mais peut se combiner avec une permission distincte de s’y défendre.","lore":"Le prédateur défend avant d’avoir décidé de défendre. Tant qu’il n’est pas véritablement surpris, la perception de l’attaque suffit à déclencher une réponse corporelle plus rapide que le coût normal d’une garde consciente.","groupe_actuel":"Mo’sen › Voie I — Mosenine — 8 PTV","statut_regle":"correction","changements":"Réflexe de chasse **1/round → 1/scène** (texte du livre V6) : une Défense active gratuite chaque round contredisait la létalité. Surpuissance : **scène → fin du round, 1/scène** (livre V6). La note « renforcement de durée proposé » n''est pas appliquée. Crête : le contrecoup du livre V6 est rétabli. C''est le ressort mo''sen face à Surcadence (Homo Superior) et Déchaînement (Ad''rak)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-crete-de-mosenine', 'Crête de Mosenine', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Début du round — gratuit — 1/scène","texte_court":"en R, 1/scène, au début d''un round : +1 PA ce round, réservé au Déplacement, au Pugilat, à la Mêlée, à la Défense active ou à un effort physique. Ensuite, plus aucune technique de Mosenine jusqu''à la fin de la scène. Ne se cumule avec aucun autre gain de PA.","texte_reference":"Une fois par scène, au début d’un round et sans PA d’activation, gagnez 1 PA réservé au Déplacement, Pugilat, Mêlée, à la Défense active ou à un effort physique significatif. Les autres techniques de Mosenine restent disponibles ensuite ; les gains directs de PA ne se cumulent pas.","lore":"La crête libère d’un seul coup la Mosenine accumulée. Le Mo’sen gagne une poussée physique immédiate, mais son organisme entre ensuite dans une phase où aucune nouvelle pointe hormonale comparable ne peut être rappelée.","groupe_actuel":"Mo’sen › Voie I — Mosenine — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_mo_sen_sens_du_predateur', 'Sens du prédateur', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"prérequis de Triangulation écrit une seule fois."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-thermovision', 'Thermovision', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"a","acces":"R","activation":"Passif","texte_court":"en R, tu vois les écarts de chaleur importants : un corps chaud dans le noir, dans une fumée légère ou derrière un camouflage visuel ordinaire. Une isolation thermique adaptée te trompe.","texte_reference":"Le Mo''sen peut percevoir naturellement les différences thermiques importantes. Il distingue notamment un organisme chaud : dans l''obscurité ; dans une fumée légère ; derrière un camouflage visuel ordinaire. Une isolation thermique appropriée fonctionne normalement.","lore":"La chaleur devient une couche naturelle de la vision Mo’sen. Un corps chaud se détache dans l’obscurité ou la fumée légère tant que rien n’isole réellement sa signature thermique.","groupe_actuel":"Mo’sen › Voie II — Sens du prédateur — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-gouter-l-air', 'Goûter l''air', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"R","activation":"Passif","texte_court":"en R, tu remarques une présence récente, du sang, une fumée, une substance volatile ou une contamination évidente. L''analyse précise demande la Compétence adaptée.","texte_reference":"Les organes sensoriels du Mo''sen lui permettent de « goûter » chimiquement son environnement. Il peut remarquer : présence récente d''un individu ; sang ; fumée ; substance volatile ; contamination évidente. L''analyse précise demande toujours une compétence adaptée.","lore":"Le Mo’sen lit la chimie ambiante avec ses organes sensoriels. Sang, fumée, passage récent ou contamination volatile laissent dans l’air un goût distinct, indice biologique plutôt qu’analyse de laboratoire.","groupe_actuel":"Mo’sen › Voie II — Sens du prédateur — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-triangulation-predatrice', 'Triangulation prédatrice', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":"Passif","texte_court":"en R, à 10 m, tu opposes ta Perception à la Furtivité grâce aux signatures que tu perçois, même sans bonne ligne de vue. Demande Thermovision ou Goûter l''air ; un masquage adapté l''empêche.","texte_reference":"À 10 m, opposez votre Perception à la Furtivité grâce aux signatures sensorielles que vous pouvez réellement percevoir, même sans bonne ligne de vue. Le talent n’accorde pas à lui seul un sens non acquis ; un masquage adapté peut l’empêcher.\n\nThermovision ou Goûter l’air restent des prérequis alternatifs. Le talent ne donne pas le sens non acheté.","lore":"Odeur, chaleur, vibrations et sons graves ne sont jamais évalués séparément. Le Mo’sen les croise instinctivement jusqu’à reconstituer où se cache une proie que les yeux seuls ne pourraient plus suivre.","groupe_actuel":"Mo’sen › Voie II — Sens du prédateur — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-verrou-sensoriel', 'Verrou sensoriel', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Après détection — scène","texte_court":"en R, une cible détectée reste repérée (position approximative) toute la scène, à 20 m au plus. Le verrou cesse si elle sort de portée ou masque ses signatures. Aucune ligne de tir.","texte_reference":"Le verrou conserve pour la scène la position approximative d’une cible détectée à 20 m maximum. Il cesse si elle quitte cette portée ou masque effectivement les signatures employées, sans créer une ligne de tir.","lore":"Une cible correctement détectée laisse dans la mémoire sensorielle une signature composite. Tant qu’elle reste proche et ne masque pas réellement ses traces, le Mo’sen continue d’en sentir la position approximative à travers foule et obscurité.","groupe_actuel":"Mo’sen › Voie II — Sens du prédateur — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_mo_sen_cuirasse_metabolique', 'Cuirasse métabolique', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. L''inversion avec le Thalsios (qui avait mieux pour moins) est corrigée côté Thalsios."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-digestion-selective', 'Digestion sélective', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":"Passif","texte_court":"en R, +3 pour résister à un poison ou une toxine ingérés. Pas d''immunité.","texte_reference":"Lorsqu''un poison ou une toxine a été ingéré, le Mo''sen bénéficie de : +3 à son test de résistance. Il ne s''agit pas d''une immunité universelle aux poisons.","lore":"Le système digestif Mo’sen filtre avec une efficacité prédatrice ce qui a été avalé. Les toxines ingérées rencontrent une chimie faite pour trier nourriture et menace plutôt qu’un simple estomac humanoïde.","groupe_actuel":"Mo’sen › Voie III — Cuirasse métabolique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-osteodermes-renforces', 'Ostéodermes renforcés', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"R","activation":"Passif","texte_court":"en R, ton Armure corporelle passe de 1 à 2.","texte_reference":"L’Armure corporelle du Mo''sen passe de : 1 à 2.","lore":"Les plaques sous-cutanées s’épaississent jusqu’à constituer une protection permanente. Le Mo’sen porte désormais sur lui une armure vivante plus dense, issue de sa propre croissance plutôt que d’un équipement ajouté.","groupe_actuel":"Mo’sen › Voie III — Cuirasse métabolique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-angle-de-cuirasse', 'Angle de cuirasse', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R","activation":"Réaction gratuite — 1/round","texte_court":"en R, 1/round, sans PA : quand un coup physique que tu vois venir touche une zone cuirassée, −2 aux dégâts restants après l''Armure. Rien contre une attaque qui vise une zone peu protégée.","texte_reference":"Une fois par round, lorsqu’un coup physique perçu touche une zone réellement cuirassée, réduisez de 2 les dégâts restants après l’Armure, sans PA. Cela ne couvre pas une attaque visant une partie non protégée.\n\nUne attaque visant explicitement une zone peu cuirassée n’est pas réduite.","lore":"Le Mo’sen sait offrir à l’impact la partie la plus dure de ses plaques. Voir venir le coup lui permet de tourner juste assez pour que la zone naturellement blindée absorbe une part supplémentaire de la violence.","groupe_actuel":"Mo’sen › Voie III — Cuirasse métabolique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-carapace-de-combat', 'Carapace de combat', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Actif — 1 PA — scène","texte_court":"en R, 1 PA : Armure corporelle 3 jusqu''à la fin de la scène, à la place des 2 d''Ostéodermes.","texte_reference":"Pour 1 PA, portez votre Armure corporelle à 3 jusqu’à la fin de la scène. Cette valeur remplace les 2 d’Ostéodermes, sans ajouter une seconde couche corporelle.","lore":"Muscles et ostéodermes se contractent ensemble et transforment momentanément la peau en véritable cuirasse biologique. La mobilité reste possible, mais chaque mouvement se fait dans un corps devenu plus fermé et plus dense.","groupe_actuel":"Mo’sen › Voie III — Cuirasse métabolique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'extral', 'extral_baseanh', 'Baséanh', NULL, '{"nature":"extral","chemin":["Baséanh"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_baseanh_pharmacopee_des_tardollas', 'Pharmacopée des Tardollas', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"délai de l''Antidote repris du livre V6. Limites en double de Culture de secours retirées. Antidote reste distinct de Conversion thérapeutique (Croix Verte) : l''un cultive un contre-agent à partir d''un échantillon, l''autre adapte un traitement existant."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-culture-de-secours', 'Culture de secours', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":"Préparation","texte_court":"en R, une préparation remplace le matériel de premiers soins et donne +3 aux premiers soins et à la Stabilisation qui l''utilisent.","texte_reference":"Vos cultures préparées remplacent le matériel de premiers soins et donnent +3 aux tests de premiers soins ou de Stabilisation qui les utilisent. Les consommations réelles, la capacité des Tardollas et les effets normaux du soin restent applicables.\n\nIl faut disposer d’une préparation réelle ; les emplacements de Tardolla et ses consommations restent applicables.","lore":"Pour un Baséanh, beaucoup d’outils médicaux sont d’abord des fonctions biologiques. Coagulant, antiseptique ou gel nutritif peuvent être cultivés sur place lorsque la trousse manque mais que la vie doit être stabilisée.","groupe_actuel":"Baséanh › Voie I — Pharmacopée des Tardollas — 8 PTV","statut_regle":"correction","changements":"délai de l''Antidote repris du livre V6. Limites en double de Culture de secours retirées. Antidote reste distinct de Conversion thérapeutique (Croix Verte) : l''un cultive un contre-agent à partir d''un échantillon, l''autre adapte un traitement existant."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-antidote-cible', 'Antidote ciblé', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"R","activation":"","texte_court":"en R, une préparation, environ 10 minutes après un échantillon de l''agent encore actif : la cible traitée refait son test de résistance avec +3. Les dégâts déjà subis restent.","texte_reference":"Après avoir obtenu un échantillon d''un poison, toxique ou agent infectieux encore actif, le Baséanh peut produire un contre-agent temporaire. Une cible traitée peut effectuer : un nouveau test de résistance avec +3. Ça ne ressuscite pas un mort et ne retire pas des dégâts déjà infligés.","lore":"La pharmacopée baséanne part toujours d’un agent réel. Une fois poison ou infection étudié, le Baséanh cultive un contre-agent conçu pour offrir au corps une seconde occasion de résister plutôt qu’une guérison miraculeuse.","groupe_actuel":"Baséanh › Voie I — Pharmacopée des Tardollas — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-catalyse-therapeutique', 'Catalyse thérapeutique', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R","activation":"Traitement — dix minutes — 1/cible/scène","texte_court":"en R, après dix minutes et un test de Médecine difficulté 15 réussi, la cible récupère 4 + DR PV, une fois par cible et par scène. Aucun membre ne repousse.","texte_reference":"Après dix minutes et un test de Médecine difficulté 15 réussi, rendez 4 + DR PV, une fois par cible et par scène. Aucun membre ne repousse et aucune séquelle n’est effacée.","lore":"La médecine baséanne accélère les processus que l’organisme possède déjà. Après quelques minutes de traitement, tissus et circulation reprennent plus efficacement leur travail, sans prétendre remplacer un membre ou effacer une séquelle.","groupe_actuel":"Baséanh › Voie I — Pharmacopée des Tardollas — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-banque-vivante', 'Banque vivante', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"","texte_court":"en R, quatre préparations actives au lieu de deux. Avec un échantillon viable que tu sais cultiver, tu en fais une copie stable avant la fin de la scène, sans laboratoire. Ni organisme très complexe, ni artefact surnaturel, ni propriété dont tu ignores le fonctionnement.","texte_reference":"Le Baséanh peut maintenir : 4 préparations actives au lieu de 2. De plus, avec un échantillon biologique viable qu''il sait cultiver, il peut en créer une copie stable avant la fin de la scène sans laboratoire complet. Ça ne permet pas de reproduire : organisme immensément complexe ; artefact surnaturel ; propriété dont il ignore complètement le fonctionnement.","lore":"Les Tardollas servent aussi de réserve biologique mobile. Un Baséanh expérimenté peut y maintenir davantage de préparations et conserver un échantillon viable assez longtemps pour le reproduire sans recréer ce qu’il ne comprend pas.","groupe_actuel":"Baséanh › Voie I — Pharmacopée des Tardollas — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_baseanh_arsenal_biologique', 'Arsenal biologique', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Purge : « immédiatement proches » précisé en « adjacentes ». Ressort face au Rocréen : le Baséanh choisit son effet à la culture et consomme une préparation ; le Rocréen tire de ses glandes sans préparation, mais à usage compté par scène."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-jet-glandulaire', 'Jet glandulaire', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":"Actif — 1 PA","texte_court":"en R, 1 PA : tu projettes une préparation à 10 m (Agilité + Tir contre Défense physique).","texte_reference":"Pour 1 PA, projetez avec précision une préparation à 10 m maximum : Agilité + Tir + 1d10e contre Défense physique. Le talent ne fournit pas de préparation et le simple rejet biologique reste inné.","lore":"Les Tardollas ne servent pas qu’au soin. Le Baséanh peut projeter leur contenu à distance, transformant sa propre pharmacopée en vecteur de combat selon ce qu’il a réellement préparé.","groupe_actuel":"Baséanh › Voie II — Arsenal biologique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-toxine-cultivee', 'Toxine cultivée', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"R","activation":"","texte_court":"en R, une préparation de neurotoxine. Exposée, la cible fait Vigueur + Constitution difficulté 15 ; en échec, −3 aux tests physiques jusqu''à la fin de son prochain round. Une protection hermétique l''arrête.","texte_reference":"Le Baséanh peut préparer une neurotoxine de combat. Sur exposition suffisante : Vigueur + Constitution difficulté 15. En échec : −3 aux tests physiques jusqu''à la fin du prochain round. Une protection hermétique empêche normalement l''exposition.","lore":"Le Baséanh élève une neurotoxine comme d’autres préparent des munitions. Son efficacité dépend de l’exposition et de la physiologie de la cible, ce qui rend une protection hermétique aussi pertinente qu’une bonne résistance corporelle.","groupe_actuel":"Baséanh › Voie II — Arsenal biologique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-secretion-de-guerre', 'Sécrétion de guerre', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R","activation":"Culture ; PA du Jet glandulaire","texte_court":"en R, à la culture, choisis : corrosive (DGT 5, ignore 2 Armure) ou adhésive (membre ou objet collé ; se libérer : 1 PA et Vigueur + Athlétisme difficulté 15). Sur un objet immobile, pas de jet d''attaque.","texte_reference":"Lors de la culture, choisissez une sécrétion corrosive (DGT 5, ignore 2 Armure) ou adhésive (membre ou objet collé ; libération : 1 PA et Vigueur + Athlétisme difficulté 15). Le choix précède le tir ; aucun jet d’attaque n’est nécessaire sur un objet immobile dans des conditions ordinaires.\n\nLa substance est physique : exposition, compatibilité biologique et protections hermétiques appropriées restent applicables.","lore":"Une Tardolla de guerre peut être cultivée pour ronger ou pour coller. Dans les deux cas, le Baséanh ne lance pas un pouvoir abstrait : il projette une substance réelle dont la chimie impose ensuite ses propres contraintes.","groupe_actuel":"Baséanh › Voie II — Arsenal biologique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-purge-explosive', 'Purge explosive', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Réaction — 1 PA — 1/scène","texte_court":"en R, réaction 1 PA, 1/scène, au contact : tu purges une préparation offensive sur toutes les créatures adjacentes, alliés compris. Seule cette préparation est perdue.","texte_reference":"Pour 1 PA en Réaction, une fois par scène au contact, purgez une seule préparation offensive pour exposer les créatures immédiatement proches, alliés compris. Seule cette préparation est perdue ; les protections, l’évitement matériel possible et les résistances restent applicables.\n\nC’est la purge sélective et maîtrisée qui est apprise, non l’existence des glandes ; l’ancienne expulsion biologique incontrôlée n’est pas effacée.","lore":"Acculé au contact, le Baséanh peut sacrifier tout son stock d’un coup. Les glandes se vident autour de lui dans une décharge biologique qui affecte chacun assez proche pour recevoir la préparation choisie.","groupe_actuel":"Baséanh › Voie II — Arsenal biologique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_baseanh_quadrimanie_maitrisee', 'Quadrimanie maîtrisée', NULL, '{"nature":"extral","forme":"deux_portes","forme_lot":"2 portes","verrou":"ordre_paliers","portes":{"A":"Mains libres","B":"Mains d''atelier"},"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-coordination-independante', 'Coordination indépendante', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":"A","palier_double":null,"acces":"R","activation":"Passif — manipulation gratuite 1/round","texte_court":"en R, tes quatre mains ignorent le malus de main non dominante ; une manipulation simple gratuite par round (saisir, ranger, passer un outil). Ni attaque, ni Défense, ni rechargement.","texte_reference":"Vos quatre mains ignorent le malus de main non dominante ; gagnez une manipulation manuelle simple gratuite par round avec vos mains libres : saisir un outil accessible, le ranger ou le passer d’une main à l’autre. Ni attaque, Défense, rechargement ni action complexe gratuite.","lore":"Chez le Baséanh entraîné, aucune des quatre mains n’est une auxiliaire maladroite. Chacune peut prendre l’outil principal avec la même précision, même si cette quadrimanie n’invente jamais des actions supplémentaires.","groupe_actuel":"Baséanh › Voie III — Quadrimanie maîtrisée — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-rechargement-quadrimanuel', 'Rechargement quadrimanuel', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":"A","palier_double":null,"acces":"R","activation":"Rechargement gratuit — 1/round","texte_court":"en R, 1/round : tu recharges sans PA une arme ou un appareil simple avec des munitions à portée de main. Pas d''arme lourde ni de rechargement complexe.","texte_reference":"Une fois par round, rechargez sans PA une arme ou un appareil simple avec vos mains libres et des munitions immédiatement accessibles. Les armes lourdes et les rechargements à installation ou étapes complexes restent exclus.","lore":"Une paire maintient l’arme pendant que l’autre nourrit le mécanisme. Sur les équipements adaptés, le rechargement cesse d’interrompre le rythme d’action du Baséanh parce que ses mains ne travaillent jamais toutes sur la même étape.","groupe_actuel":"Baséanh › Voie III — Quadrimanie maîtrisée — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-ancrage-manuel', 'Ancrage manuel', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":"B","palier_double":null,"acces":"R","activation":"Passif","texte_court":"en R, pour une tâche de précision, tu ignores une circonstance défavorable due seulement à un support instable ou à ton propre mouvement.","texte_reference":"Pour une tâche de précision où le Baséanh peut utiliser ses membres supplémentaires pour se stabiliser : ignorer une circonstance défavorable provenant uniquement d''un support instable ou d''un mouvement du corps.","lore":"Quatre membres permettent au Baséanh de créer son propre support. Sur une tâche fine, deux mains travaillent tandis que les autres stabilisent le corps ou l’outil, annulant l’instabilité que subirait un opérateur bipède.","groupe_actuel":"Baséanh › Voie III — Quadrimanie maîtrisée — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-deuxieme-paire-experte', 'Deuxième paire experte', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":"B","palier_double":null,"acces":"R","activation":"","texte_court":"en R, quand une tâche manuelle gagnerait à un assistant qui tient, stabilise ou manipule un second outil, tu te donnes toi-même l''Assistance +2. Jamais sur une attaque, une Défense ou un pouvoir personnel.","texte_reference":"Lorsqu''une tâche manuelle bénéficierait réellement d''un assistant dont le rôle serait uniquement : tenir ; stabiliser ; présenter ; maintenir ouvert ; manipuler un second outil le Baséanh peut assurer lui-même ce rôle avec sa seconde paire de bras. Il reçoit alors : le bonus normal d''Assistance +2. Jamais sur : attaque ; Défense active ; pouvoir strictement personnel.","lore":"Là où un technicien humain demanderait quelqu’un pour tenir, ouvrir ou présenter une pièce, le Baséanh emploie sa seconde paire de bras. Il devient son propre assistant tant que la tâche reste vraiment manuelle.","groupe_actuel":"Baséanh › Voie III — Quadrimanie maîtrisée — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'extral', 'extral_rocreen', 'Rocréen', NULL, '{"nature":"extral","chemin":["Rocréen"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_rocreen_regeneration_du_noyau', 'Régénération du Noyau', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Régénération active **1 PA, 1/round → 2 PA, 1/scène** (livre V6). 4 à 6 PV par round sans plafond rendaient le Rocréen presque increvable. Noyau obstiné : **1/scénario** (livre V6 ; le site n''avait pas de limite). « Ignore évidemment cette Technique » retiré : le trait Noyau rocréen dit comment le Noyau tombe."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-cicatrisation-humide', 'Cicatrisation humide', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":"Passif","texte_court":"en R, immergé ou bien hydraté, tes Saignements ordinaires cessent, tes plaies ne s''infectent pas d''elles-mêmes et ta récupération naturelle hors combat est doublée.","texte_reference":"Lorsque le Rocréen est immergé ou maintenu dans un environnement suffisamment humide pour hydrater complètement ses tissus : tout effet de Saignement ordinaire cesse immédiatement. Une blessure ainsi maintenue ne développe pas non plus normalement de complication infectieuse provenant simplement de son ouverture. De plus : toute récupération naturelle de PV hors combat est doublée tant qu’elle s’effectue dans ces conditions.","lore":"Les tissus rocréens se réparent mieux lorsque l’eau les maintient dans leur milieu préféré. Saignement et infection ordinaire reculent, tandis que la récupération naturelle profite directement de cette hydratation complète.","groupe_actuel":"Rocréen › Voie I — Régénération du Noyau — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-regeneration-active', 'Régénération active', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"R","activation":"Actif — 1 PA — 1/round ; à 0 PV : tous les PA","texte_court":"en R, 2 PA, 1/scène, Noyau intact : tu récupères 4 PV, 6 si tu es immergé ou abondamment hydraté. À 0 PV et Stabilisé, tu peux l''utiliser au round suivant : elle prend toute ton activation.","texte_reference":"Au-dessus de 0 PV et avec le Noyau intact, 1 PA rend 4 PV, ou 6 en immersion ou hydratation abondante, une fois par round. À 0 PV Stabilisé, la régénération occupe toute l’activation du round suivant et consomme tous ses PA, sans autre action ; aucun membre ne repousse instantanément.\n\nLa condition de Noyau intact est impérative. À 0 PV Stabilisé, aucune autre action, déplacement, attaque ou second soin ne peut être effectué ce round, quel que soit le nombre de PA.","lore":"Le Rocréen peut ordonner à son noyau de privilégier la reconstruction immédiate. Les tissus referment brutalement les lésions, et l’eau disponible accélère encore ce processus sans transformer une repousse complexe en miracle instantané.","groupe_actuel":"Rocréen › Voie I — Régénération du Noyau — 8 PTV","statut_regle":"correction","changements":"Régénération active **1 PA, 1/round → 2 PA, 1/scène** (livre V6). 4 à 6 PV par round sans plafond rendaient le Rocréen presque increvable. Noyau obstiné : **1/scénario** (livre V6 ; le site n''avait pas de limite). « Ignore évidemment cette Technique » retiré : le trait Noyau rocréen dit comment le Noyau tombe."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-reconstruction-organique', 'Reconstruction organique', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R","activation":"","texte_court":"en R, Noyau intact, tu refais un œil, un doigt, un organe, un segment ou un membre en quelques heures à quelques jours, avec eau et nourriture. Hors combat.","texte_reference":"Le Rocréen peut reconstruire biologiquement un œil, un doigt, un morceau d’organe, un segment périphérique ou un membre entier tant que son noyau reste intact. Ce processus demande de quelques heures à plusieurs jours selon l’importance, avec hydratation et nutrition suffisantes. Ce n’est pas une capacité de combat.","lore":"Le noyau contient le plan vivant dont le reste du corps peut être rebâti. Avec temps, eau et nutriments, œil, organe ou membre repoussent comme une continuation lente de la même morphologie.","groupe_actuel":"Rocréen › Voie I — Régénération du Noyau — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-noyau-obstine', 'Noyau obstiné', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"","texte_court":"en R, 1/scénario : quand tu tombes à 0 PV ou moins sans atteindre ton seuil de mort, Noyau intact, tu es Stabilisé automatiquement à la fin du round. On peut t''achever avant.","texte_reference":"Quand le Rocréen tombe à 0 PV ou moins sans atteindre son seuil de mort : si son noyau est intact, il est automatiquement Stabilisé à la fin du round. Il peut toujours être achevé avant cela. Un coup détruisant réellement le noyau ignore évidemment cette Technique.","lore":"Le noyau reste la dernière certitude biologique du Rocréen. Tant qu’il survit intact, le corps tente spontanément de revenir à un état stable même après un effondrement qui aurait laissé une autre espèce mourir sans intervention.","groupe_actuel":"Rocréen › Voie I — Régénération du Noyau — 8 PTV","statut_regle":"correction","changements":"Régénération active **1 PA, 1/round → 2 PA, 1/scène** (livre V6). 4 à 6 PV par round sans plafond rendaient le Rocréen presque increvable. Noyau obstiné : **1/scénario** (livre V6 ; le site n''avait pas de limite). « Ignore évidemment cette Technique » retiré : le trait Noyau rocréen dit comment le Noyau tombe."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_rocreen_reseau_psychique', 'Réseau psychique', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"note « elle demande une validation explicite » retirée ; l''ouverture aux non-télépathes est conservée (voir Q3). Partage : « ignore jusqu''à −3 dus au partage d''attention » (malus défini nulle part) devient « sans malus »."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-lien-de-banc', 'Lien de banc', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Actif — 1 PA par lien","texte_court":"en SR/R, 1 PA par lien : tu relies au banc un allié consentant, même non télépathe, à 20 m, pour la scène. Cinq alliés au plus.","texte_reference":"Pour 1 PA, intégrez au banc un allié consentant même dépourvu de don télépathique, à 20 m maximum pour la scène. Jusqu’à cinq alliés peuvent être reliés, chaque nouveau lien étant établi séparément ; l’échange naturel entre télépathes compatibles reste inné.\n\nL’ouverture aux non-télépathes est une nouvelle exception à la restriction du lore, pas une capacité gratuite déjà acquise ; elle demande une validation explicite.","lore":"Le banc commence par une connexion mentale simple entre esprits compatibles. Mots, intentions et signaux circulent sans voix tant que les deux consciences restent assez proches pour maintenir le lien.","groupe_actuel":"Rocréen › Voie II — Réseau psychique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-partage-sensoriel', 'Partage sensoriel', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"SR/R","activation":"Actif — 1 PA — scène","texte_court":"en SR/R, 1 PA : pour la scène, tu suis un sens qu''un membre du banc te partage, sans perdre les tiens et sans malus.","texte_reference":"Pour 1 PA, suivez pour la scène un sens volontairement partagé par un membre du banc tout en conservant vos propres perceptions. Ignorez jusqu’à −3 dus au seul partage d’attention entre ces deux points de vue, sans action supplémentaire ni emprunt de Compétence.","lore":"Le Rocréen peut emprunter momentanément un sens à un membre du réseau. Il regarde, écoute ou ressent depuis un autre corps sans oublier que le sien demeure quelque part, vulnérable et toujours réel.","groupe_actuel":"Rocréen › Voie II — Réseau psychique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-relais-psychique', 'Relais psychique', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"SR/R","activation":"Passif","texte_court":"en SR/R, le banc s''étend par trois intermédiaires au plus, 20 m entre chaque lien. Un lien coupé coupe sa branche.","texte_reference":"Étendez le banc par trois intermédiaires au maximum, avec 20 m au plus entre chaque lien. La coupure d’un lien coupe la branche concernée ; pas de liaison transcontinentale.","lore":"Le réseau rocréen sait passer par ses propres membres. Une conscience transmet le lien à une autre et permet au banc de s’étendre dans un bâtiment sans prétendre abolir toute limite de distance.","groupe_actuel":"Rocréen › Voie II — Réseau psychique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-conscience-distribuee', 'Conscience distribuée', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R","activation":"Passif — banc établi","texte_court":"en SR/R, les membres du banc sont avertis des menaces que perçoit l''un d''eux : ils ne sont pas Surpris par elles et gagnent +3 à leur première Défense active physique du round contre une attaque ainsi annoncée. Les défenses restent payantes.","texte_reference":"Les membres du banc sont avertis des menaces réellement perçues par les autres, ne sont pas Surpris par elles et gagnent +3 à leur première Défense active physique du round contre une attaque ainsi annoncée. Les défenses restent payantes, les corps doivent pouvoir réagir et aucune ligne de tir n’est créée.\n\nLe banc comprend au plus cinq alliés et le Rocréen. Une seule circonstance favorable équivalente s’applique par test ; consentement et continuité du réseau restent requis.","lore":"Dans un banc psychique, ce que voit l’un devient une alerte pour les autres. Le Rocréen connecté n’a pas besoin de tourner la tête vers une menace qu’un membre du réseau perçoit déjà clairement.","groupe_actuel":"Rocréen › Voie II — Réseau psychique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_rocreen_glandes_rocreennes', 'Glandes rocréennes', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Ventouses (1 PTV) devient le texte du trait Quadrimanie rocréenne, qui était vide (**−1 PTV**, changement de règle). La voie passe de 5 talents / 9 PTV à 4 / 8, comme les autres."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-jet-d-encre', 'Jet d''encre', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":"Actif — 1 PA — 1/scène","texte_court":"en R, 1 PA, 1/scène : encre sur une cible à 10 m ou une zone de 2 m : −3 à la vision gênée jusqu''au nettoyage (1 PA) ou à la sortie de la zone.","texte_reference":"Une fois par scène, pour 1 PA, projetez de l’encre sur une cible à 10 m ou une zone de 2 m maximum : la vision gênée subit −3 jusqu’au nettoyage ou à la sortie de la zone. Un nettoyage simple accessible coûte 1 PA.","lore":"Une glande expulse une encre épaisse qui remplit les yeux et macule la zone. La gêne persiste jusqu’à ce qu’elle soit nettoyée ou contournée, exactement comme on attendrait d’un liquide opaque réellement projeté.","groupe_actuel":"Rocréen › Voie III — Glandes rocréennes — 9 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-colle-organique', 'Colle organique', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"R","activation":"Actif — 1 PA","texte_court":"en R, 1 PA : tir à 10 m (Agilité + Tir contre Défense). Se décoller : 1 PA et Vigueur + Athlétisme difficulté 15. Un vêtement collé n''immobilise pas tout le corps.","texte_reference":"Pour 1 PA, tirez votre colle à 10 m, avec Agilité + Tir + 1d10e contre la Défense applicable. Une liaison collée se rompt pour 1 PA et Vigueur + Athlétisme difficulté 15, sans immobiliser tout un corps pour un simple vêtement touché.","lore":"Le mucus rocréen peut devenir une colle de combat assez forte pour immobiliser un membre, fixer une arme ou solidariser deux surfaces. Se libérer revient alors à vaincre une matière physique, pas une injonction abstraite.","groupe_actuel":"Rocréen › Voie III — Glandes rocréennes — 9 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-venin-rocreen', 'Venin rocréen', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R","activation":"Actif — 1 PA — 1/scène","texte_court":"en R, 1 PA, 1/scène : tir à 10 m ; touchée et exposée, la cible fait Vigueur + Constitution difficulté 15 ou subit −3 aux tests physiques jusqu''à la fin de son prochain round.","texte_reference":"Une fois par scène, pour 1 PA, projetez votre venin sur une cible à 10 m : après une attaque réussie et une exposition effective, Vigueur + Constitution difficulté 15 évite −3 aux tests physiques jusqu’à la fin du prochain round. Une protection hermétique appropriée empêche l’exposition.","lore":"Le venin rocréen attaque la physiologie plutôt que l’armure. S’il atteint réellement l’organisme, il ralentit et affaiblit brièvement le corps ; une enveloppe hermétique peut donc rendre la toxine parfaitement inutile.","groupe_actuel":"Rocréen › Voie III — Glandes rocréennes — 9 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-cocktail-glandulaire', 'Cocktail glandulaire', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Actif — 1 PA — compteurs des deux sécrétions","texte_court":"en R, 1 PA : deux effets glandulaires connus sur la même cible, en un seul jet. Chacun garde sa résistance et consomme son usage.","texte_reference":"Pour 1 PA, combinez deux effets glandulaires connus et applicables à la même cible dans un seul jet d’attaque. Chaque effet conserve sa résistance, ses protections et son compteur d’utilisation, tous deux consommés.","lore":"Les glandes rocréennes peuvent expulser deux sécrétions dans le même jet. Les effets se mêlent sur la cible parce que le corps a réellement combiné les produits avant la projection.","groupe_actuel":"Rocréen › Voie III — Glandes rocréennes — 9 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'extral', 'extral_thalsios', 'Thalsios', NULL, '{"nature":"extral","chemin":["Thalsios"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_thalsios_densification', 'Densification', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Muscle tassé **DGT 4 → 2** (livre V6, et « Pugilat tassé DGT 2 » au Bestiaire). DGT 4 dépassait les griffes mo''sennes et le Pugilat ad''rak en R. Vieux cuir **Armure 3 → 2** (livre V6). Le Mo''sen redevient le peuple le mieux cuirassé. Densification osseuse garde son coût du site (1 ; le JSON dit 2). Phrase « plusieurs siècles » retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-densification-osseuse', 'Densification osseuse', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"a","acces":"R","activation":"Passif","texte_court":"en R, Armure corporelle 1, cumulable avec une armure portée compatible, jamais avec une autre Armure corporelle.","texte_reference":"Votre densification vous accorde Armure corporelle 1, cumulable avec une armure portée réellement compatible. Elle ne s’ajoute pas à une autre couche d’Armure corporelle.","lore":"Avec le temps, l’ossature thalsiosse devient assez dense pour encaisser comme une protection interne. L’armure vient de la matière même du corps plutôt que d’une plaque ajoutée sur la peau.","groupe_actuel":"Thalsios › Voie I — Densification thalsiosse — 7 PTV","statut_regle":"correction","changements":"Muscle tassé **DGT 4 → 2** (livre V6, et « Pugilat tassé DGT 2 » au Bestiaire). DGT 4 dépassait les griffes mo''sennes et le Pugilat ad''rak en R. Vieux cuir **Armure 3 → 2** (livre V6). Le Mo''sen redevient le peuple le mieux cuirassé. Densification osseuse garde son coût du site (1 ; le JSON dit 2). Phrase « plusieurs siècles » retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-peau-saturee', 'Peau saturée', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"R","activation":"Passif","texte_court":"en R, +3 pour résister à la chaleur ou au feu ordinaires. Rien contre un plasma ou une température extrême.","texte_reference":"La peau extrêmement humide du Thalsios lui donne : +3 pour résister aux effets de chaleur ou de feu ordinaires. Ça ne protège pas sérieusement d''un plasma ou d''une température physiquement extrême.","lore":"La peau thalsiosse retient tant d’humidité qu’une partie de la chaleur ordinaire y est absorbée et répartie. Flammes et températures raisonnables peinent davantage à la brûler, sans faire d’elle une protection contre un plasma.","groupe_actuel":"Thalsios › Voie I — Densification thalsiosse — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-muscle-tasse', 'Muscle tassé', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":"Passif","texte_court":"en R, ton Pugilat inflige DGT 2 au lieu de 1.","texte_reference":"Votre Pugilat utilise DGT 4 au lieu de DGT 1. Il s’agit de la valeur de base du coup naturel, pas d’un +4 cumulé avec une autre arme.","lore":"Le muscle thalsios se compacte au lieu de simplement grossir. Ses impacts deviennent plus lourds parce qu’une masse musculaire anormalement dense transmet davantage de force dans chaque coup naturel.","groupe_actuel":"Thalsios › Voie I — Densification thalsiosse — 7 PTV","statut_regle":"correction","changements":"Muscle tassé **DGT 4 → 2** (livre V6, et « Pugilat tassé DGT 2 » au Bestiaire). DGT 4 dépassait les griffes mo''sennes et le Pugilat ad''rak en R. Vieux cuir **Armure 3 → 2** (livre V6). Le Mo''sen redevient le peuple le mieux cuirassé. Densification osseuse garde son coût du site (1 ; le JSON dit 2). Phrase « plusieurs siècles » retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-vieux-cuir', 'Vieux cuir', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Passif","texte_court":"en R, ton Armure corporelle passe à 2.","texte_reference":"Votre Armure corporelle passe à 3, en remplacement de Densification osseuse et sans cumuler plusieurs couches corporelles. Ce stade de densification n’exige pas d’avoir vécu plusieurs siècles.","lore":"La densification avancée donne à la peau et aux tissus l’aspect du vieux cuir épais même chez un individu relativement jeune. Ce stade physiologique constitue une seconde couche de protection corporelle permanente.","groupe_actuel":"Thalsios › Voie I — Densification thalsiosse — 7 PTV","statut_regle":"correction","changements":"Muscle tassé **DGT 4 → 2** (livre V6, et « Pugilat tassé DGT 2 » au Bestiaire). DGT 4 dépassait les griffes mo''sennes et le Pugilat ad''rak en R. Vieux cuir **Armure 3 → 2** (livre V6). Le Mo''sen redevient le peuple le mieux cuirassé. Densification osseuse garde son coût du site (1 ; le JSON dit 2). Phrase « plusieurs siècles » retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_thalsios_sensibilite_thalsiosse', 'Sensibilité thalsiosse', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"limites de Résonance écrites une fois. Ressort face aux autres sens de zone : le Thalsios lit par contact avec un milieu (le Talass par le Talwa, bloqué par les barrières dimensionnelles ; le Mo''sen par chaleur et chimie)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-lecture-vibratoire', 'Lecture vibratoire', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"a","acces":"R","activation":"Passif","texte_court":"en R, au contact du sol, d''un mur, d''une structure ou de l''eau : +3 pour lire les vibrations faibles à 10 m (nombre de sources, direction, rythme). Pas d''identité.","texte_reference":"En contact avec le milieu, gagnez +3 pour distinguer et interpréter les vibrations faibles jusqu’à 10 m : nombre approximatif de sources, direction et rythme. Le talent n’identifie ni une personne ni sa Nature sans indices supplémentaires.","lore":"Sol, mur ou eau peuvent servir de membrane au Thalsios. En contact avec eux, il perçoit les déplacements importants transmis dans le matériau et en retire direction et distance approximatives.","groupe_actuel":"Thalsios › Voie II — Sensibilité thalsiosse — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-branchies-barometriques', 'Branchies barométriques', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"R","activation":"Passif","texte_court":"en R, à 5 m, +3 en Perception pour détecter une présence hors de vue par les mouvements d''air ou d''eau. Rien dans le vide ou un milieu isolé.","texte_reference":"À 5 m, gagnez +3 aux tests de Perception utilisant les mouvements d’air ou d’eau pour détecter une présence hors de votre champ visuel. Les milieux isolés, le vide ou l’absence de perturbation perceptible restent des limites.","lore":"Les branchies thalsiosses sentent les microvariations de pression comme une peau extrêmement sensible. Un corps qui déplace brutalement l’air proche peut donc être remarqué même hors du champ visuel.","groupe_actuel":"Thalsios › Voie II — Sensibilité thalsiosse — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-resonance-holographique', 'Résonance holographique', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":"Passif — acclimatation terrestre","texte_court":"en R, acclimaté à la Terre : après une fluctuation ressentie, +3 pour en situer la source et distinguer une transition V/SR/R d''une contrainte durable ou d''un résidu. Ni espèce, ni forme V cachée.","texte_reference":"Après une fluctuation ressentie, gagnez +3 pour en situer la source locale et distinguer une transition V/SR/R d’une contrainte durable ou d’un résidu perceptible. Cela ne donne pas l’espèce, ne voit pas la forme V cachée et ne force aucune Révélation.\n\nL’acclimatation terrestre prolongée reste nécessaire ; le Thalsios n’identifie aucune espèce et ne voit pas une forme cachée à V.","lore":"Les Thalsios acclimatés à la Terre finissent par sentir quand l’Hologramme se tend autour d’une présence ou d’une transition. Ils perçoivent la variation sans recevoir automatiquement l’identité de ce que le Voile est en train de traduire.","groupe_actuel":"Thalsios › Voie II — Sensibilité thalsiosse — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-cartographie-vibratoire', 'Cartographie vibratoire', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Actif — 1 PA — scène","texte_court":"en R, 1 PA : pour la scène, carte précise des mouvements à 10 m par les milieux qui te transmettent leurs vibrations. Surfaces découplées et isolations la bloquent. Aucune ligne de tir.","texte_reference":"Pour 1 PA, maintenez pendant la scène la carte précise des mouvements à 10 m via les milieux qui vous transmettent leurs vibrations. Les surfaces découplées et isolations adaptées la bloquent ; aucune ligne de vue ou de tir n’est créée.","lore":"En laissant les vibrations dessiner l’espace, le Thalsios obtient pour quelques secondes une carte des mouvements autour de lui. Fumée, obscurité et invisibilité optique comptent peu tant que le milieu transmet encore les oscillations.","groupe_actuel":"Thalsios › Voie II — Sensibilité thalsiosse — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_thalsios_constance_thalsiosse', 'Constance thalsiosse', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"phrase d''ambiance d''Habituation retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-invariance', 'Invariance', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/Scène","texte_court":"V/SR/R, 1/scène : relance un test de Stress ou de résistance mentale. Une seule relance de talent par test.","texte_reference":"Le personnage peut relancer : un test de Stress ou de résistance à un effet mental. On applique la règle générale : un même test ne bénéficie jamais de plusieurs relances de Talent.","lore":"Le Thalsios peut refuser une première conclusion émotionnelle ou mentale et reprendre une fois sa résistance. Cette seconde tentative exprime sa stabilité profonde, pas une immunité générale à ce qui le touche.","groupe_actuel":"Thalsios › Voie III — Constance thalsiosse — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-retard-de-reaction', 'Retard de réaction', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"V/SR/R","activation":"Réaction — 1/Scène","texte_court":"V/SR/R, réaction 1/scène : après un échec contre un effet mental durable, l''effet ne commence qu''à la fin de ton prochain tour. Il n''est pas annulé.","texte_reference":"Après avoir échoué à une résistance mentale produisant un effet durable : l''effet ne commence qu''à la fin du prochain tour du Thalsios. Il dispose donc d''un bref instant où son comportement reste pleinement sien. Ça n''annule pas l''effet.","lore":"Même lorsqu’une influence mentale gagne, elle ne trouve pas toujours immédiatement prise sur un Thalsios. Son esprit conserve un court intervalle de comportement autonome avant que l’effet durable ne commence réellement.","groupe_actuel":"Thalsios › Voie III — Constance thalsiosse — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-retour-a-l-equilibre', 'Retour à l''équilibre', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"","texte_court":"V/SR/R : un effet mental mesuré en rounds dure 1 round de moins (minimum 1) ; un effet de scène sans nouveau test t''en accorde un à la fin de ton prochain round. Une fois par application.","texte_reference":"Lorsqu''un effet mental possède une durée mesurée en rounds : réduire sa durée de 1 round, minimum 1. Si l''effet dure normalement toute la scène sans nouveau test : le Thalsios obtient un nouveau test de résistance à la fin de son prochain round. Une seule fois par application.","lore":"La Constance tend naturellement à ramener l’esprit vers son état précédent. Les influences temporaires s’épuisent plus vite, et celles qui devraient durer toute une scène rencontrent au moins une occasion supplémentaire d’être rejetées.","groupe_actuel":"Thalsios › Voie III — Constance thalsiosse — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-habituation', 'Habituation', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"","texte_court":"V/SR/R : après avoir résisté à une source mentale, elle ne peut plus t''imposer exactement le même effet de la scène. Un pouvoir différent du même adversaire fonctionne normalement.","texte_reference":"Après avoir réussi à résister à une source mentale précise pendant une scène : cette même source ne peut plus lui imposer exactement le même effet pendant le reste de la scène. Il s''est stabilisé contre elle. Une capacité réellement différente du même adversaire fonctionne normalement. Ça crée quelque chose d''assez thalsios : le premier assaut psychique est dangereux ; le cinquième identique commence à ne plus faire grand-chose.","lore":"Une première résistance réussie laisse dans la constance thalsiosse un nouvel équilibre. La même source ne peut plus produire exactement la même intrusion mentale pendant la scène, comme si l’esprit s’était accordé contre elle.","groupe_actuel":"Thalsios › Voie III — Constance thalsiosse — 8 PTV","statut_regle":"correction","changements":"phrase d''ambiance d''Habituation retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'extral', 'extral_voie_commune', 'Voie commune', NULL, '{"nature":"extral","chemin":["Voie commune"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_voie_commune_protocoles_de_continuite', 'Protocoles de Continuité', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Transition en chaîne garde son coût (3) au palier II, comme Stase II chez le Vampire. Coordination de Continuité sort de la voie : c''est de l''assistance en combat, sans lien avec le Voile (section Organisation). L''article du site qui doublonne les Protocoles est à retirer."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-revelation-drillee', 'Révélation drillée', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"a","acces":"V/SR/R","activation":"1/Scène","texte_court":"V/SR/R, 1/scène, pendant ton tour : V→SR, SR→R ou V→R sans payer de PA. Rien contre une Révélation bloquée.","texte_reference":"Pendant son propre tour, le personnage peut effectuer V→SR, SR→R ou V→R sans payer le PA normalement requis. Le Talent ne permet pas de contourner une Révélation impossible ou activement bloquée.","lore":"Changer d’état fait partie de l’entraînement, pas d’un rituel hésitant. La Révélation devient un geste intégré au mouvement du tour, tant qu’aucune force extérieure ne l’empêche réellement.","groupe_actuel":"Protocoles de Continuité — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-repli-reflexe', 'Repli réflexe', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"SR/R","activation":"Réaction — 1/Scène","texte_court":"SR/R, réaction 1/scène : quand un imprévu menace d''exposer ta Vérité (témoin, caméra, patrouille), tu reviens à V sans PA. Rien n''est effacé de ce qui a été vu. Ton camp ne peut pas provoquer l''imprévu pour le déclencher.","texte_reference":"Lorsqu’un changement réel et imprévu de situation menace soudain d’exposer sa Vérité - nouvel observateur, caméra, patrouille, irruption, changement de contexte comparable - le personnage peut revenir immédiatement à V sans payer de PA. Le Talent n’efface rien de ce qui a déjà été vu et ne peut pas être déclenché par une mise en scène volontaire du personnage ou de ses alliés uniquement pour obtenir un repli gratuit.","lore":"Quand un nouveau témoin menace soudain de voir trop loin, la Continuité privilégie le réflexe de couverture. Le personnage replie immédiatement sa Révélation, sans effacer ce que quelqu’un a déjà eu le temps d’observer.","groupe_actuel":"Protocoles de Continuité — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-transition-en-chaine', 'Transition en chaîne', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Gratuit — 1/scène","texte_court":"1/scène, sans coût : tes transitions ne coûtent plus de PA jusqu''à la fin de la scène, aux fenêtres normales. Elle remplace Révélation drillée.","texte_reference":"Une fois par scène et sans coût d’activation, les transitions personnelles ne coûtent aucun PA jusqu’à la fin de la scène. Elles restent possibles uniquement aux fenêtres normales, sans contourner blocage, créer des actions ou soigner par changement de forme.","lore":"La Continuité permet d’enchaîner plusieurs transitions sans laisser chaque passage dévorer une part du rythme d’action. Cela reste une succession d’états possibles, jamais une source cachée d’actions supplémentaires.","groupe_actuel":"Protocoles de Continuité — 7 PTV","statut_regle":"correction","changements":"Transition en chaîne garde son coût (3) au palier II, comme Stase II chez le Vampire. Coordination de Continuité sort de la voie : c''est de l''assistance en combat, sans lien avec le Voile (section Organisation). L''article du site qui doublonne les Protocoles est à retirer."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'extral', 'extral_homo_superior', 'Homo Superior', NULL, '{"nature":"extral","chemin":["Homo Superior"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_homo_superior_homeostasie_celltech', 'Homéostasie celltech', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"vocabulaire logiciel retiré (« rechargement de page, sauvegarde… »). Réserve nanitique garde le +3 du site (le JSON dit +1 « par ensemble de blessures »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-purge-systemique', 'Purge systémique', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Réaction — 1/Scène","texte_court":"réaction 1/scène : après un échec contre poison, toxine, maladie ou contamination, relance. Le second résultat est définitif.","texte_reference":"Après l’échec d’un test de résistance contre poison, toxine, maladie ou contamination biologique, le personnage déclenche une adaptation nanitique et relance le test. Le second résultat est définitif.","lore":"Face à un agent biologique hostile, l’essaim modifie brutalement sa réponse interne. Ce second passage ne promet pas l’immunité ; il offre au corps une adaptation immédiate à ce qui vient précisément de le dépasser.","groupe_actuel":"Homo Superior — Humain AIDH › Homéostasie celltech — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-reserve-nanitique', 'Réserve nanitique', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"V/SR/R","activation":"Passif — 1/scénario","texte_court":"1/scénario : le premier soin qui te rend des PV en rend +3. Pas sur la récupération naturelle, Cycle de réparation ou une régénération.","texte_reference":"Une fois par scénario, le premier soin réel reçu vous rend 3 PV supplémentaires. La récupération naturelle, Cycle de réparation et toute régénération indépendante sont exclus ; cette utilisation est distincte de celle de Cycle de réparation.\n\nLe bonus intervient uniquement si le soin rend effectivement des PV, sans dépasser le maximum. Rechargement de page, sauvegarde, nouveau combat et transition V/SR/R ne renouvellent pas cette utilisation. Le premier soin éligible du scénario consomme cette réserve.","lore":"Lorsqu’un soin réel ouvre déjà un cycle de reconstruction, les nanites y injectent leur propre réserve. Elles amplifient légèrement la récupération sans pouvoir se nourrir indéfiniment de leur propre travail.","groupe_actuel":"Homo Superior — Humain AIDH › Homéostasie celltech — 8 PTV","statut_regle":"correction","changements":"vocabulaire logiciel retiré (« rechargement de page, sauvegarde… »). Réserve nanitique garde le +3 du site (le JSON dit +1 « par ensemble de blessures »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-compensation-traumatique', 'Compensation traumatique', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Réaction — 1/Scène","texte_court":"réaction 1/scène : quand une blessure ou une Altération compromet une fonction sans détruire l''organe, tu reportes la conséquence fonctionnelle à la fin de la scène. Rien contre un membre amputé ou un œil détruit.","texte_reference":"Lorsqu’une blessure ou une Altération compromet une fonction corporelle sans l’avoir physiquement détruite, les nanites réorganisent temporairement tissus et contrôle neural et reportent la conséquence fonctionnelle jusqu’à la fin de la scène. Peut concerner une jambe endommagée, un bras traumatisé, une vision brouillée ou un choc neural ; ne recrée pas un membre amputé, un œil détruit ou un organe irrémédiablement perdu.","lore":"Les nanites ne font pas repousser ce qui a disparu, mais elles savent contourner une fonction blessée. Elles redistribuent commande nerveuse et soutien tissulaire pour maintenir provisoirement l’usage d’un membre ou d’un sens encore physiquement présent.","groupe_actuel":"Homo Superior — Humain AIDH › Homéostasie celltech — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-cycle-de-reparation', 'Cycle de réparation', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Actif — 1 PA — 1/scénario","texte_court":"1 PA, 1/scénario, essaim fonctionnel : tu récupères 6 PV. Ta récupération naturelle hors combat est doublée.","texte_reference":"Une fois par scénario, dépensez 1 PA pour récupérer 6 PV si vous êtes conscient, vivant et votre essaim fonctionnel. Votre récupération naturelle hors combat reste doublée ; Réserve nanitique ne s’applique pas à ce cycle.\n\nLa récupération naturelle doublée est permanente hors combat, pas une deuxième activation du soin. Nouvelle scène, sauvegarde et transition V/SR/R ne renouvellent pas l’utilisation de scénario. Aucun essaim défaillant, mort ou inconscient ne peut être soigné par cette activation.","lore":"L’essaim celltech entretient en permanence un travail de réparation que l’organisme ordinaire n’effectuerait qu’au repos. Quand le porteur lui laisse la main, la fermeture des lésions s’accélère nettement.","groupe_actuel":"Homo Superior — Humain AIDH › Homéostasie celltech — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_homo_superior_conditionnement_suprahumain', 'Conditionnement suprahumain', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Surcadence : interdiction de cumul ajoutée (seule la Crête l''avait). Ressorts face aux Ad''rak : le bond et le PA de l''Homo Superior marchent Voilé, ceux de l''Ad''rak demandent la Révélation et la mêlée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-poussee-myofibrillaire', 'Poussée myofibrillaire', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Lors d’un Déplacement — 1/round","texte_court":"1/round : ton Déplacement à 1 PA va jusqu''au double à l''horizontale, ou à sa distance normale à la verticale. Un vrai danger demande un test.","texte_reference":"Une fois par round, votre Déplacement à 1 PA permet un bond horizontal jusqu’au double de sa distance normale, ou vertical jusqu’à cette distance normale. Un vrai danger exige toujours un test ; aucune suspension en vol.","lore":"Les fibres artificiellement optimisées peuvent libérer une poussée de déplacement hors des standards humains. Un obstacle banal devient franchissable dans l’élan, sans transformer pour autant une impossibilité réelle en simple formalité.","groupe_actuel":"Homo Superior — Humain AIDH › Conditionnement suprahumain — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-reflexe-d-impact', 'Réflexe d''impact', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"V/SR/R","activation":"Réaction — 1 PA — 1/round","texte_court":"réaction 1 PA, 1/round : quand une attaque t''inflige une Altération, tu évites la chute, le désarmement, la perte d''équilibre ou l''incapacité momentanée. Les dégâts restent.","texte_reference":"Quand une attaque réussie lui inflige une Altération, le personnage peut empêcher une conséquence immédiate de chute, désarmement, perte d’équilibre ou incapacité momentanée liée au choc. Les dégâts restent intégralement appliqués ; une destruction physique réelle n’est pas annulée.","lore":"L’Homo Superior absorbe l’information du choc avant d’en subir toutes les conséquences motrices. Il peut garder son arme, ses appuis ou son équilibre quand l’impact aurait normalement provoqué une perte de contrôle immédiate.","groupe_actuel":"Homo Superior — Humain AIDH › Conditionnement suprahumain — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-fonctionnement-sous-contrainte', 'Fonctionnement sous contrainte', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Passif — 1/round","texte_court":"1/round : une douleur, un choc ou un vertige purement physiologique n''interrompt pas l''action que tu peux encore accomplir. Ne lève ni immobilisation, ni inconscience, ni effet mental, ni malus chiffré.","texte_reference":"Lorsqu’une douleur, un choc, un vertige ou une perturbation purement physiologique devrait interrompre une action en cours ou empêcher le personnage d’accomplir une action qu’il reste physiquement capable d’exécuter, il peut poursuivre normalement. Ne supprime ni immobilisation, ni inconscience, ni effet mental, ni membre détruit, ni malus numérique indépendant, ni incapacité matérielle réelle.","lore":"Le conditionnement suprahumain apprend au corps à poursuivre malgré douleur, choc ou vertige tant que la fonction physique existe encore. La discipline ne répare rien : elle empêche seulement le trouble de devenir l’ordre qui fait cesser l’action.","groupe_actuel":"Homo Superior — Humain AIDH › Conditionnement suprahumain — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-surcadence-somatique', 'Surcadence somatique', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/Scène","texte_court":"1/scène, au début de ton activation : +1 PA ce round (4 au plus). Le PA non dépensé se perd. Ne se cumule avec aucun autre gain de PA.","texte_reference":"Au début d’une activation, le personnage gagne +1 PA pour le round, pouvant atteindre 4 PA. Le PA inutilisé disparaît à la fin du round et l’Initiative n’est pas modifiée.","lore":"Pendant quelques secondes, métabolisme et contrôle neuromusculaire dépassent leur cadence normale. Le corps gagne un temps d’action supplémentaire qu’il ne pourrait soutenir au-delà du round sans sortir de son régime prévu.","groupe_actuel":"Homo Superior — Humain AIDH › Conditionnement suprahumain — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_homo_superior_neurodiscipline_aidh', 'Neurodiscipline AIDH', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Cloisonnement reste à 1/round (texte et livre concordent), malgré le verdict « fort » du rapport : il ne touche pas la survie."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-verrou-neuroemotionnel', 'Verrou neuroémotionnel', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Réaction — 1/Scène","texte_court":"réaction 1/scène : un échec de Stress qui t''aggraverait de plusieurs niveaux ne t''aggrave que d''un (Normal → Tendu au lieu de Paniqué).","texte_reference":"Après l’échec d’un test de Stress qui devrait aggraver l’état de plusieurs niveaux, limiter l’aggravation à un seul niveau. Par exemple, Normal → Paniqué devient Normal → Tendu. L’échec reste un échec.","lore":"Lorsqu’un choc psychique devrait faire basculer trop loin l’état émotionnel, le verrou AIDH casse la chute en deux. L’échec reste présent, mais le système refuse qu’une seule secousse traverse plusieurs seuils d’un coup.","groupe_actuel":"Homo Superior — Humain AIDH › Neurodiscipline AIDH — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-reflexe-conditionne', 'Réflexe conditionné', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"V/SR/R","activation":"Réaction gratuite — 1/scène","texte_court":"1/scène : Défense active physique sans PA, avec +3, même Surpris. Les autres avantages de la Surprise restent.","texte_reference":"Une fois par scène, effectuez une Défense active physique sans PA avec +3, même Surpris. Il faut rester physiquement capable de réagir ; les autres avantages de la Surprise ne sont pas effacés.","lore":"L’entraînement AIDH prépare une défense jusque dans la surprise. Le corps peut lever une garde avant que la conscience n’ait fini d’admettre l’attaque, à condition qu’il dispose encore du temps d’action nécessaire.","groupe_actuel":"Homo Superior — Humain AIDH › Neurodiscipline AIDH — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-cloisonnement-fonctionnel', 'Cloisonnement fonctionnel', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"1/round","texte_court":"1/round, avant un test : Tendu se joue comme Normal, Paniqué comme Tendu. Ton état ne change pas.","texte_reference":"Avant un test, le personnage isole temporairement ses fonctions cognitives de son état émotionnel : Tendu utilise les règles de dé de Normal ; Paniqué utilise celles de Tendu. L’état réel de Stress ne change pas.","lore":"La Neurodiscipline apprend à séparer provisoirement émotion et exécution. La peur ou la tension existent encore, mais les circuits chargés d’accomplir la tâche sont maintenus à distance de leur perturbation la plus immédiate.","groupe_actuel":"Homo Superior — Humain AIDH › Neurodiscipline AIDH — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-traitement-parallele', 'Traitement parallèle', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/round","texte_court":"1/round : une action purement mentale ou d''interface à 1 PA (scan, lecture tactique, transfert, commande simple) devient gratuite. Jamais offensive, contestée ou physique.","texte_reference":"Une fois par round, le personnage peut réaliser gratuitement en parallèle une action purement cognitive ou d’interface qui coûterait normalement 1 PA : scan, lecture tactique, transfert de données, commande simple d’interface ou consultation immédiate. L’action gratuite ne peut être offensive, contestée, modifier directement l’état, la position, les PV ou les capacités d’un autre acteur, ni constituer une seconde action physique. Une interface ou un système réellement utilisable reste nécessaire.","lore":"Une partie de l’architecture cognitive reste disponible pour une tâche simple d’interface ou de lecture pendant que le reste agit. Cette pensée parallèle ne devient jamais une seconde action complexe cachée dans le même instant.","groupe_actuel":"Homo Superior — Humain AIDH › Neurodiscipline AIDH — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_homo_superior_patchs_tatoues', 'Patchs tatoués', NULL, '{"nature":"extral","forme":"progression","forme_lot":"progression courte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"note « Intégration à contrôler/développer lors du lot » retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-phasage-de-l-equipement', 'Phasage de l''équipement', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Actif — 1 ou 2 PA","texte_court":"1 PA pour matérialiser ou déphaser un objet lié à tes patchs, 2 PA pour une tenue, une armure ou plusieurs éléments. Rien n''est créé ni dupliqué.","texte_reference":"Pour matérialiser ou déphaser l’équipement existant lié à vos patchs tatoués AIDH, dépensez 1 PA pour un objet ou 2 PA pour une tenue, une armure ou plusieurs éléments. Les mêmes coûts s’appliquent dans les deux sens ; aucun matériel ni duplicata n’est créé.\n\nIntégration à contrôler/développer lors du lot ; aucune prétention à un test d’interface déjà exécuté pour les Extrals.","lore":"Les patchs tatoués intégrés au soldat servent de supports de liaison à son équipement. Ce Talent maîtrise son phasage et son déphasage ; il ne fournit pas l’équipement lié.","groupe_actuel":"Homo Superior — Humain AIDH › Patchs tatoués AIDH","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'extral', 'extral_ad_rak', 'Ad''rak', NULL, '{"nature":"extral","chemin":["Ad''rak"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_ad_rak_poigne', 'Poigne', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Colosse et Puissance de guerre redistribués en Poigne et Masse, mêmes talents, mêmes coûts (le site avait 7 et 9 PTV). Note de version de Projection retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-saisie-ecrasante', 'Saisie écrasante', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Passif","texte_court":"en SR/R, après une saisie réussie sur une cible nettement plus petite, tu la maintiens immobilisée, gagnes +3 pour garder la prise et peux la porter à demi-Déplacement.","texte_reference":"Après une saisie réussie sur une cible sensiblement plus petite, maintenez son immobilisation, gagnez +3 pour conserver la prise et pouvez la transporter à demi-Déplacement. Aucune saisie, attaque ou action supplémentaire n’est créée.","lore":"Une fois refermée, la saisie d’un Ad’rak devient une cage de muscles et de poids. Une créature nettement plus petite doit réellement vaincre cette masse pour retrouver sa liberté de mouvement.","groupe_actuel":"Ad’rak — origine restreinte › Puissance de guerre — 9 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-briseur-de-prise', 'Briseur de prise', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"SR/R","activation":"Réaction — 1 PA — 1/round","texte_court":"en SR/R, réaction 1 PA, 1/round : saisi, retenu ou entravé physiquement, tu tentes aussitôt de te libérer (Vigueur + Athlétisme contre l''opposition).","texte_reference":"Lorsqu’il est saisi, retenu ou entravé par une contrainte physique contre laquelle sa force peut réellement agir, l’Ad’rak peut immédiatement tenter de la rompre avec Vigueur + Athlétisme contre l’opposition applicable, sans attendre son activation.","lore":"Être saisi ne signifie pas être tenu lorsqu’on possède la puissance d’un Ad’rak. Le corps répond immédiatement contre la contrainte physique, arrachant la prise avant que l’adversaire n’ait le temps de la transformer en contrôle durable.","groupe_actuel":"Ad’rak — origine restreinte › Colosse Ad’rak — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-passer-en-force', 'Passer en force', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R","activation":"1/Scène","texte_court":"en R, 1/scène : après un échec non narratif à un test de Vigueur pour briser, arracher, soulever, retenir ou déplacer un obstacle, tu réussis avec DR 0. Le MJ impose une conséquence : 2 PV ignorant l''Armure, bruit énorme, objet abîmé, temps perdu…","texte_reference":"Après un échec non narratif à un test de Vigueur visant uniquement à briser, arracher, soulever, retenir ou déplacer un obstacle matériel, l’Ad’rak peut choisir de réussir quand même avec DR 0. Le MJ impose alors une conséquence appropriée : 2 PV ignorant l’Armure à cause de l’effort, position compromise, bruit énorme, objet manipulé endommagé, perte de temps ou autre conséquence directement liée.","lore":"Certaines traditions Ad’rak considèrent qu’un obstacle matériel n’a pas à gagner simplement parce qu’il a résisté une première fois. Le guerrier force alors le résultat, quitte à payer l’ouverture par la douleur, le bruit ou la casse.","groupe_actuel":"Ad’rak — origine restreinte › Puissance de guerre — 9 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-projection-de-masse', 'Projection de masse', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Actif — 1 PA — cible déjà saisie","texte_court":"en R, 1 PA, sur une cible déjà saisie de taille comparable ou inférieure : Vigueur + Pugilat contre Vigueur + Athlétisme ; elle recule de 2 m + DR et tombe. Contre une surface solide : ton DGT de Pugilat + DR, Armure applicable.","texte_reference":"Pour 1 PA, projetez une cible déjà saisie, de taille comparable ou inférieure : Vigueur + Pugilat contre Vigueur + Athlétisme ; en réussite, elle recule de 2 m + DR et est renversée. Une collision réelle avec une surface solide inflige votre DGT de Pugilat + DR, Armure applicable.\n\nLa distance et la chute sont conservées ; le DR remplace l’ancien terme de collision, ne s’ajoute pas une deuxième fois à la marge d’une autre attaque.","lore":"La projection Ad’rak n’est pas un tour de lutte subtil : elle saisit la différence de force et la transforme en trajectoire. Une cible assez légère quitte le sol et découvre brutalement ce que vaut son environnement comme point d’arrêt.","groupe_actuel":"Ad’rak — origine restreinte › Puissance de guerre — 9 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_ad_rak_masse', 'Masse', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"« aucune Altération identique n''est doublée » (obscur) retiré. Mur vivant reste distinct de Tenir la ligne : le Mur arrête, la Ligne suit."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-ancrage-de-masse', 'Ancrage de masse', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Passif","texte_court":"en SR/R, +3 pour résister à une projection, un renversement, une poussée ou un déplacement forcé physique. Rien contre une téléportation ou une gravité anormale.","texte_reference":"Circonstances favorables (+3) pour résister à une projection, un renversement, une poussée ou un déplacement forcé purement physique. Ne protège pas contre téléportation, gravité anormale ou déplacement surnaturel sans prise physique.","lore":"Un Ad’rak sait quand cesser de bouger. Il abaisse son centre de gravité, verrouille ses appuis et oppose au choc toute la masse d’un corps conçu pour que le monde recule avant lui.","groupe_actuel":"Ad’rak — origine restreinte › Colosse Ad’rak — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-mur-vivant', 'Mur vivant', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"R","activation":"Réaction — 1 PA — 1/round","texte_court":"en R, réaction 1 PA, 1/round : une créature de taille comparable ou inférieure traverse ta zone : Vigueur + Athlétisme contre sa Vigueur ou son Agilité + Athlétisme. Réussi, elle s''arrête à ton contact.","texte_reference":"Pour 1 PA en Réaction, une fois par round, barrez le passage à une créature de taille comparable ou inférieure qui traverse votre zone immédiate : Vigueur + Athlétisme contre Vigueur ou Agilité + Athlétisme. En réussite, son déplacement s’arrête à votre contact.","lore":"La largeur d’un Ad’rak peut devenir une fortification mobile. Lorsqu’il décide qu’un passage est fermé, le franchir revient à déplacer physiquement celui qui tient la ligne.","groupe_actuel":"Ad’rak — origine restreinte › Colosse Ad’rak — 7 PTV","statut_regle":"correction","changements":"« aucune Altération identique n''est doublée » (obscur) retiré. Mur vivant reste distinct de Tenir la ligne : le Mur arrête, la Ligne suit."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-charge-de-rupture', 'Charge de rupture', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R","activation":"1/scène — après Déplacement et attaque payés","texte_court":"en R, 1/scène : après un Déplacement vers une cible et une attaque de mêlée qui lui inflige au moins 1 dégât dans le même round, tu la renverses ou la repousses de 2 m + DR. Une cible plus massive oppose sa Vigueur.","texte_reference":"Une fois par scène, après un Déplacement vers une cible suivi d’une attaque de mêlée réussie qui lui inflige au moins 1 dégât dans le même round, renversez-la ou repoussez-la de 2 m + DR. Les actions restent payantes et une cible sensiblement plus massive peut opposer sa Vigueur ; aucune Altération identique n’est doublée.","lore":"Une charge Ad’rak ne cherche pas seulement à blesser. L’élan entier continue après l’impact, convertissant la masse du colosse en poussée capable de renverser ou de chasser une cible moins bien ancrée.","groupe_actuel":"Ad’rak — origine restreinte › Colosse Ad’rak — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-impact-titanesque', 'Impact titanesque', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"1/scène — attaque normalement payée","texte_court":"en R, 1/scène, annoncé avant une attaque de Pugilat ou de Mêlée : +4 DGT si elle réussit, sans pénalité de Défense.","texte_reference":"Une fois par scène, annoncez avant une attaque de Pugilat ou Mêlée un coup entièrement consacré à la puissance : +4 DGT en cas de réussite, sans pénalité à votre Défense. Une Altération réellement obtenue peut prendre la forme d’une projection ou destruction locale plausible.","lore":"L’Ad’rak sacrifie toute prudence pour un seul coup d’une violence totale. Le geste expose sa garde, mais ce qu’il atteint reçoit la force d’une masse lancée sans réserve, assez pour projeter ou rompre un appui.","groupe_actuel":"Ad’rak — origine restreinte › Puissance de guerre — 9 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_ad_rak_traditions_guerrieres', 'Traditions guerrières', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Tenir la ligne et Duel : coût en PA et fréquence de la colonne du site passent dans le texte (Tenir la ligne semblait gratuit et sans jet)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-tenir-la-ligne', 'Tenir la ligne', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Réaction — 1 PA — 1/round","texte_court":"V/SR/R, réaction 1 PA, 1/round : une créature à ton contact tente de te contourner ou de quitter ta zone : tu te replaces pour lui barrer encore le passage, si le terrain le permet. Tu ne l''arrêtes pas ; pas d''attaque gratuite.","texte_reference":"Quand une créature à portée de mêlée tente de passer physiquement à côté de l’Ad’rak ou de quitter sa zone immédiate et que la géométrie le permet, il peut se repositionner pour continuer à lui barrer le passage. Aucune attaque gratuite n’est créée.","lore":"Tenir la ligne consiste à rester exactement là où la fuite adverse voudrait trouver un passage. L’Ad’rak ajuste ses appuis et son corps pour continuer à fermer la zone sans transformer cette vigilance en attaque gratuite.","groupe_actuel":"Ad’rak — origine restreinte › Traditions guerrières Ad’rak — 8 PTV","statut_regle":"correction","changements":"Tenir la ligne et Duel : coût en PA et fréquence de la colonne du site passent dans le texte (Tenir la ligne semblait gratuit et sans jet)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-corps-pour-corps', 'Corps pour corps', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"V/SR/R","activation":"Réaction — 1 PA","texte_court":"V/SR/R, réaction 1 PA : tu prends la place d''un allié adjacent comme cible d''une attaque de mêlée et fais ta Défense active dans ce même PA.","texte_reference":"Pour 1 PA en Réaction, remplacez un allié adjacent comme cible d’une attaque de mêlée et effectuez votre Défense active physique contre cette attaque dans ce même PA. Aucune autre attaque n’est annulée.","lore":"Les guerriers Ad’rak apprennent à protéger les leurs avec leur propre volume. Un pas latéral suffit parfois à remplacer un allié dans la trajectoire d’une attaque et à faire du colosse la cible voulue.","groupe_actuel":"Ad’rak — origine restreinte › Traditions guerrières Ad’rak — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-duel-de-guerre', 'Duel de guerre', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"1/Scène","texte_court":"V/SR/R, 1/scène : après une attaque de mêlée réussie, tu désignes la cible jusqu''à la fin de ta prochaine activation. Si elle attaque quelqu''un d''autre à ta portée de mêlée, réaction 1 PA : tu l''attaques en mêlée.","texte_reference":"Après avoir réussi une attaque de mêlée contre une cible, l’Ad’rak peut la désigner jusqu’à la fin de sa prochaine activation. Si elle attaque volontairement quelqu’un d’autre tout en restant à sa portée de mêlée, l’Ad’rak peut dépenser 1 PA en Réaction pour effectuer immédiatement une attaque de mêlée contre elle.","lore":"Le duel Ad’rak crée une menace simple : ignorer le guerrier expose immédiatement son flanc. Tant que l’ennemi reste à portée, détourner son attention devient un choix qui peut être puni sur-le-champ.","groupe_actuel":"Ad’rak — origine restreinte › Traditions guerrières Ad’rak — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-ne-pas-rompre', 'Ne pas rompre', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Réaction — 1 PA — 1/scène","texte_court":"V/SR/R, réaction 1 PA, 1/scène : quand une blessure t''impose Tendu ou Paniqué, tu ignores jusqu''à la fin de la scène le Stress dû aux seules blessures.","texte_reference":"Une fois par scène, lorsqu’une blessure impose Tendu ou Paniqué, dépensez 1 PA en Réaction pour ignorer jusqu’à la fin de la scène les conséquences de Stress dues aux seules blessures. Les causes psychologiques indépendantes, PV, Altérations, Agonie et incapacités physiques restent inchangés.","lore":"La tradition refuse qu’une blessure physique suffise à briser la ligne intérieure du combattant. Même paniqué par sa propre chair, l’Ad’rak conserve pour quelques minutes la discipline nécessaire pour agir sans sombrer entièrement dans l’état qui l’a frappé.","groupe_actuel":"Ad’rak — origine restreinte › Traditions guerrières Ad’rak — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_ad_rak_arts_de_nel_akna_formes_anciennes', 'Arts de Nel''Akna · Formes anciennes', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Enchaînement : la limite 1/round de la colonne du site passe dans le texte."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-garde-du-sanctuaire', 'Garde du Sanctuaire', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"V/SR/R, ta Défense active contre la mêlée peut utiliser Agilité + Mêlée ou Agilité + Pugilat au lieu d''Esquive. Toujours 1 PA.","texte_reference":"Pour une Défense active contre une attaque de mêlée, le pratiquant peut utiliser Agilité + Mêlée + 1d10e ou Agilité + Pugilat + 1d10e à la place d’Agilité + Esquive + 1d10e. Le coût reste 1 PA.","lore":"La Garde du Sanctuaire préfère une arme ou le corps entraîné à une esquive dispersée. Le pratiquant reçoit l’attaque dans une structure de parade conçue pour protéger un lieu, un maître ou un passage.","groupe_actuel":"Ad’rak — origine restreinte › Arts de Nel’Akna — 16 PTV › Formes anciennes — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-cercle-interieur', 'Cercle intérieur', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"V/SR/R","activation":"Après Défense active — saisie gratuite — 1/round","texte_court":"V/SR/R, 1/round : après une Défense active réussie contre la mêlée, tu établis une saisie sans PA ni jet si tu as un membre libre.","texte_reference":"Une fois par round, après une Défense active réussie contre une attaque de mêlée, établissez une saisie sans PA ni second jet si vous avez un membre libre et une prise physiquement possible. La défense reste payante, aucune immobilisation impossible n’est créée.","lore":"Les formes anciennes de Nel’Akna apprennent à ne jamais répondre au choc de face. Après avoir détourné l’attaque, le combattant glisse autour de l’adversaire et transforme la défense en nouvel angle de contrôle.","groupe_actuel":"Ad’rak — origine restreinte › Arts de Nel’Akna — 16 PTV › Formes anciennes — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-enchainement-des-anciennes-formes', 'Enchaînement des anciennes formes', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"1/round","texte_court":"V/SR/R, 1/round : après un Pugilat réussi, sans PA ni jet, une conséquence plausible : saisie, désarmement, renversement ou déplacement de 1 m.","texte_reference":"Après une attaque de Pugilat réussie, et après résolution normale des dégâts, le pratiquant peut appliquer sans PA supplémentaire et sans second jet l’une des conséquences suivantes si elle est physiquement plausible : établir une saisie, désarmer, renverser ou déplacer la cible de 1 mètre. Le Talent n’autorise pas l’impossible : la première attaque a déjà tranché la qualité de l’ouverture, mais la morphologie et les masses restent réelles.","lore":"Chez les Ad’rak, une frappe réussie n’est souvent que la première syllabe d’une phrase martiale. La même ouverture peut devenir saisie, désarmement ou chute sans qu’un second échange soit nécessaire.","groupe_actuel":"Ad’rak — origine restreinte › Arts de Nel’Akna — 16 PTV › Formes anciennes — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-retour-de-la-main-vide', 'Retour de la main vide', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Réaction — 1 PA — 1/round","texte_court":"V/SR/R, réaction 1 PA, 1/round : après une Défense active de mêlée réussie, tu ripostes en Pugilat ou en Mêlée. Une riposte n''en déclenche pas d''autre.","texte_reference":"Une fois par round, après une Défense active de mêlée réussie, dépensez 1 PA en Réaction pour riposter en Pugilat ou Mêlée. Cette riposte ne peut pas déclencher un autre Retour de la main vide.","lore":"Lorsqu’un assaillant vient mourir sur la garde de Nel’Akna, la réponse part avant qu’il ait repris sa posture. La défense réussie laisse le bras adverse ouvert et appelle immédiatement la contre-attaque.","groupe_actuel":"Ad’rak — origine restreinte › Arts de Nel’Akna — 16 PTV › Formes anciennes — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_ad_rak_arts_de_nel_akna_souffle_ecarlate', 'Arts de Nel''Akna · Souffle écarlate', NULL, '{"nature":"extral","forme":"une_porte","forme_lot":"1 porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Pas écarlate : ressort ajouté (« s''il te rapproche d''un adversaire ») pour le distinguer de Poussée myofibrillaire, au texte presque identique. Onde : coût 1 PA écrit (il manquait). Déchaînement : interdiction de cumul ajoutée ; coquille « ,, » corrigée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-souffle-profond', 'Souffle profond', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Réaction — 1/Scène","texte_court":"en SR/R, 1/scène : après un échec non narratif à un test physique où la Vigueur ou l''Agilité compte, relance le d10. Le second résultat est définitif.","texte_reference":"Après l’échec non narratif d’un test physique où la Vigueur ou l’Agilité est réellement déterminante - effort, saut, course, résistance corporelle ou maintien d’une prise - le pratiquant peut relancer le d10. Le second résultat est définitif.","lore":"Nel’Akna apprend à chercher plus loin que la première défaillance du corps. Quand force ou agilité lâchent sans catastrophe, une seconde poussée de Souffle tente de reprendre le geste avant qu’il ne soit perdu.","groupe_actuel":"Ad’rak — origine restreinte › Arts de Nel’Akna — 16 PTV › Souffle écarlate — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-pas-ecarlate', 'Pas écarlate', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"a","acces":"R","activation":"1/round","texte_court":"en R, 1/round : ton Déplacement payé normalement devient un bond jusqu''au double à l''horizontale, ou sa distance à la verticale, **s''il te rapproche d''un adversaire**. Il faut une réception praticable.","texte_reference":"Une fois par round, votre Déplacement normalement payé permet un bond jusqu’au double de sa distance normale horizontalement ou cette distance verticalement. Une réception praticable reste nécessaire ; ni vol durable ni station sur un mur.","lore":"Le Pas écarlate transforme l’élan en trajectoire anormale : mur, pente ou vide bref cessent d’être des limites ordinaires. Le pratiquant ne vole pas ; il accomplit simplement un franchissement que son corps seul n’aurait jamais permis.","groupe_actuel":"Ad’rak — origine restreinte › Arts de Nel’Akna — 16 PTV › Souffle écarlate — 8 PTV","statut_regle":"correction","changements":"Pas écarlate : ressort ajouté (« s''il te rapproche d''un adversaire ») pour le distinguer de Poussée myofibrillaire, au texte presque identique. Onde : coût 1 PA écrit (il manquait). Déchaînement : interdiction de cumul ajoutée ; coquille « ,, » corrigée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-onde-ecarlate', 'Onde écarlate', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"R","activation":"1/round","texte_court":"en R, 1 PA, 1/round : attaque de Pugilat à 5 m (Vigueur + Pugilat contre Défense), DGT de ton Pugilat, −2 à l''Armure de la cible ; au moins 1 dégât : recul de 1 m + DR. Ce n''est pas un contact : ni saisie ni Enchaînement.","texte_reference":"Le pratiquant projette son Souffle à travers un mouvement de frappe et peut effectuer une attaque de Pugilat contre une cible jusqu’à 5 mètres : Vigueur + Pugilat + 1d10e contre la Défense normale. L’Onde utilise le DGT normal du Pugilat du personnage, réduit l’Armure de la cible de 2 contre cette attaque et, si au moins 1 dégât est infligé, repousse la cible de 1 m + DR lorsque sa masse et son ancrage le permettent. L’Onde compte comme attaque de Pugilat pour son jet et ses dégâts, mais ne constitue pas un contact physique : elle ne permet ni saisie, ni désarmement physique, ni Enchaînement des anciennes formes.","lore":"Un mouvement de frappe suffit à projeter le Souffle au-delà du poing. L’impact atteint une cible distante comme si la masse du combattant avait franchi l’espace avec lui, repoussant ce qu’elle parvient réellement à ébranler.","groupe_actuel":"Ad’rak — origine restreinte › Arts de Nel’Akna — 16 PTV › Souffle écarlate — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-dechainement-ecarlate', 'Déchaînement écarlate', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Début d’activation — 1/Scène","texte_court":"en R, 1/scène, au début de ton activation : +1 PA ce round, puis choisis Vitesse (ton premier Déplacement est gratuit) ou Puissance (une attaque de Pugilat, Mêlée ou Onde réussie gagne +3 de marge pour les dégâts seulement). Ne se cumule avec aucun autre gain de PA.","texte_reference":"Jusqu’à la fin du round, le pratiquant gagne +1 PA,, puis choisit Vitesse ou Puissance. Vitesse : le premier Déplacement du round ne coûte aucun PA. Puissance : une seule attaque de Pugilat, Mêlée ou Onde écarlate réussie pendant le round augmente sa marge de +3 uniquement pour le calcul des dégâts et des effets physiques. Cela ne transforme pas le résultat du jet pour déclencher d’autres capacités ou prérequis.","lore":"Le Souffle écarlate peut envahir tout le corps pendant quelques secondes. Selon la manière dont il est libéré, il devient vitesse brutale ou puissance concentrée, toujours au prix d’un rythme impossible à maintenir longtemps.","groupe_actuel":"Ad’rak — origine restreinte › Arts de Nel’Akna — 16 PTV › Souffle écarlate — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'extral', 'extral_organisations_de_verite_voies_hors_nature', 'Organisations de Vérité (voies hors Nature)', NULL, '{"nature":"extral","chemin":["Organisations de Vérité (voies hors Nature)"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_ctu_ingenierie_de_transition', 'CTU — Ingénierie de transition', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-declassement-fonctionnel', 'Déclassement fonctionnel', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"Préparation technique","texte_court":"Avec les outils et l’appareil nécessaires, sacrifiez une fonction secondaire ou réduisez les performances pour préserver sa fonction essentielle malgré une infrastructure locale insuffisante, avec +3 au test technique. Les fonctions abandonnées restent perdues jusqu’à réparation ou réadaptation ; aucune pièce n’est créée.","texte_reference":"Avec les outils et l’appareil nécessaires, sacrifiez une fonction secondaire ou réduisez les performances pour préserver sa fonction essentielle malgré une infrastructure locale insuffisante, avec +3 au test technique. Les fonctions abandonnées restent perdues jusqu’à réparation ou réadaptation ; aucune pièce n’est créée.","lore":"Quand l’infrastructure ne suit pas, la CTU accepte de perdre de la performance pour sauver la fonction essentielle. Une technologie trop avancée est volontairement simplifiée jusqu’au niveau que l’environnement local peut réellement soutenir.","groupe_actuel":"Organisations Extrals › CTU — Californian Talasses Union — 16 PTV › Ingénierie de transition — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-emulation-de-composant', 'Émulation de composant', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"Préparation — dix minutes","texte_court":"Avec matériaux, outils et fonction connue, fabriquez un substitut temporaire en dix minutes avec +3 au test technique approprié. Il tient pour la scène d’utilisation et ne reproduit pas un principe physiquement impossible avec ces moyens.","texte_reference":"Avec matériaux, outils et fonction connue, fabriquez un substitut temporaire en dix minutes avec +3 au test technique approprié. Il tient pour la scène d’utilisation et ne reproduit pas un principe physiquement impossible avec ces moyens.","lore":"Un composant exotique introuvable peut être remplacé par une imitation fonctionnelle bricolée avec le monde disponible. Elle ne reproduit pas la technologie entière ; elle tient juste la place nécessaire pour que le système continue.","groupe_actuel":"Organisations Extrals › CTU — Californian Talasses Union — 16 PTV › Ingénierie de transition — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-standard-terrestre', 'Standard terrestre', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"","activation":"","texte_court":"Le personnage peut adapter durablement alimentation, connectique, interface ou protocole d’une technologie xéno afin qu’elle fonctionne avec un standard terrestre approprié sans exiger l’infrastructure d’origine","texte_reference":"Le personnage peut adapter durablement alimentation, connectique, interface ou protocole d’une technologie xéno afin qu’elle fonctionne avec un standard terrestre approprié sans exiger l’infrastructure d’origine","lore":"Alimentation, connectique ou protocole cessent d’être des frontières culturelles. La CTU traduit durablement l’interface xéno vers un standard terrestre cohérent afin que l’appareil puisse vivre loin de son infrastructure d’origine.","groupe_actuel":"Organisations Extrals › CTU — Californian Talasses Union — 16 PTV › Ingénierie de transition — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-prototype-de-transition', 'Prototype de transition', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"","activation":"","texte_court":"Avec temps, atelier et matériaux, le personnage peut produire un prototype local reproduisant une fonction majeure d’une technologie supérieure par des étapes intermédiaires moins avancées. Le prototype reste un objet réel : il peut être volé, cassé ou réparé","texte_reference":"Avec temps, atelier et matériaux, le personnage peut produire un prototype local reproduisant une fonction majeure d’une technologie supérieure par des étapes intermédiaires moins avancées. Le prototype reste un objet réel : il peut être volé, cassé ou réparé","lore":"L’ingénieur construit un pont technique entre deux âges. Le prototype reproduit une fonction majeure avec des solutions intermédiaires, moins élégantes mais suffisamment locales pour être entretenues, volées ou cassées comme n’importe quel objet.","groupe_actuel":"Organisations Extrals › CTU — Californian Talasses Union — 16 PTV › Ingénierie de transition — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_ctu_diffusion_technologique', 'CTU — Diffusion technologique', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-interface-vulgarisee', 'Interface vulgarisée', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"","texte_court":"Le personnage peut encapsuler une interface xéno de façon qu’un opérateur formé mais non spécialiste puisse utiliser ses fonctions prévues sans comprendre le paradigme technique complet","texte_reference":"Le personnage peut encapsuler une interface xéno de façon qu’un opérateur formé mais non spécialiste puisse utiliser ses fonctions prévues sans comprendre le paradigme technique complet","lore":"Une technologie xéno peut recevoir une façade compréhensible par un opérateur local. La CTU encapsule la complexité au lieu de l’enseigner tout entière, permettant l’usage prévu sans transmettre le paradigme complet qui se cache dessous.","groupe_actuel":"Organisations Extrals › CTU — Californian Talasses Union — 16 PTV › Diffusion technologique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-procedure-encapsulee', 'Procédure encapsulée', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"Voir règle détaillée","texte_court":"Après sa mise au point réelle, une procédure documentée donne +3 aux tests des techniciens qui l’exécutent avec les bons outils pendant une scène de travail. Elle ne leur transmet ni théorie générale ni compétence permanente.","texte_reference":"Après sa mise au point réelle, une procédure documentée donne +3 aux tests des techniciens qui l’exécutent avec les bons outils pendant une scène de travail. Elle ne leur transmet ni théorie générale ni compétence permanente.","lore":"La CTU transforme une expertise rare en procédure transmissible. Chaque étape est isolée, sécurisée et reproductible afin qu’une équipe locale puisse accomplir le processus sans posséder la théorie qui l’a rendu possible.","groupe_actuel":"Organisations Extrals › CTU — Californian Talasses Union — 16 PTV › Diffusion technologique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-atelier-distribue', 'Atelier distribué', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"","activation":"","texte_court":"Un processus complexe peut être réparti entre plusieurs ateliers ou équipes disposant chacun de moyens incomplets, puis assemblé sans exiger que chaque site maîtrise toute la chaîne technologique","texte_reference":"Un processus complexe peut être réparti entre plusieurs ateliers ou équipes disposant chacun de moyens incomplets, puis assemblé sans exiger que chaque site maîtrise toute la chaîne technologique","lore":"La CTU sait qu’un atelier incomplet peut devenir un maillon utile plutôt qu’un échec. Une fabrication complexe est divisée entre plusieurs sites, chacun produisant la partie qu’il est réellement capable de maîtriser.","groupe_actuel":"Organisations Extrals › CTU — Californian Talasses Union — 16 PTV › Diffusion technologique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-industrialisation-frugale', 'Production de terrain', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"","activation":"Préparation — temps selon le prototype","texte_court":"Vous pouvez reproduire ou réparer une fonction d’un prototype connu et testé à l’aide d’un kit mobile réellement assemblé, sans atelier fixe pour cette fonction. Les composants, outils, temps et tests restent nécessaires ; ce savoir-faire permet aussi une petite série avec une infrastructure réelle.","texte_reference":"Vous pouvez reproduire ou réparer une fonction d’un prototype connu et testé à l’aide d’un kit mobile réellement assemblé, sans atelier fixe pour cette fonction. Les composants, outils, temps et tests restent nécessaires ; ce savoir-faire permet aussi une petite série avec une infrastructure réelle.\n\nNom proposé : « Production de terrain » ; identifiant conservé, le talent achète le protocole, pas le kit ou les objets fabriqués.","lore":"Un prototype de transition peut devenir petite série lorsque l’infrastructure locale est organisée autour de ses vraies contraintes. La CTU simplifie la chaîne sans faire disparaître machines, matières ni personnel nécessaires.","groupe_actuel":"Organisations Extrals › CTU — Californian Talasses Union — 16 PTV › Diffusion technologique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_croix_verte_acclimatation_artif', 'Croix Verte — Acclimatation artificielle', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-microclimat-de-fortune', 'Microclimat de fortune', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"Préparation — dix minutes","texte_court":"En dix minutes, avec du matériel réellement approprié, aménagez une zone de 3 m de rayon pour les besoins d’une espèce connue. Elle reste viable tant que ses ressources consommables et conditions d’étanchéité le permettent ; aucune atmosphère n’apparaît sans moyen matériel.","texte_reference":"En dix minutes, avec du matériel réellement approprié, aménagez une zone de 3 m de rayon pour les besoins d’une espèce connue. Elle reste viable tant que ses ressources consommables et conditions d’étanchéité le permettent ; aucune atmosphère n’apparaît sans moyen matériel.","lore":"Avec quelques matériaux et un bon diagnostic xénobiologique, une petite zone peut être corrigée assez vite pour devenir temporairement respirable, humide ou thermiquement acceptable à une espèce donnée.","groupe_actuel":"Organisations Extrals › Croix Verte / Ligue Baséanne — 16 PTV › Acclimatation artificielle — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-substitution-metabolique', 'Substitution métabolique', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"","texte_court":"Transformer ou combiner des ressources locales afin qu’elles remplacent temporairement une ressource biologique normalement incompatible : nutriment, électrolyte, support respiratoire ou besoin métabolique comparable","texte_reference":"Transformer ou combiner des ressources locales afin qu’elles remplacent temporairement une ressource biologique normalement incompatible : nutriment, électrolyte, support respiratoire ou besoin métabolique comparable","lore":"Le besoin biologique compte plus que le produit d’origine. La Croix Verte transforme des ressources locales pour fournir nutriment, électrolyte ou support respiratoire sous une forme que l’organisme étranger peut réellement utiliser.","groupe_actuel":"Organisations Extrals › Croix Verte / Ligue Baséanne — 16 PTV › Acclimatation artificielle — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-acclimatation-transitoire', 'Acclimatation transitoire', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"","activation":"Préparation — dix minutes","texte_court":"Définissez un protocole pour une espèce et un milieu non instantanément létal, avec dix minutes de préparation et une scène de tolérance. Produits nécessaires, incompatibilités absolues et limites biologiques restent réels.","texte_reference":"Définissez un protocole pour une espèce et un milieu non instantanément létal, avec dix minutes de préparation et une scène de tolérance. Produits nécessaires, incompatibilités absolues et limites biologiques restent réels.","lore":"La Croix Verte prépare un organisme à subir pendant un temps un environnement qui n’est pas le sien. Métabolisme, respiration ou équilibre interne sont soutenus juste assez pour rendre l’opération possible sans prétendre abolir les lois physiques.","groupe_actuel":"Organisations Extrals › Croix Verte / Ligue Baséanne — 16 PTV › Acclimatation artificielle — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-habitat-de-survie', 'Habitat de survie', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"","activation":"Préparation — 1 heure pour le refuge d’urgence","texte_court":"En une heure, aménagez avec des ressources réelles un refuge compatible pour cinq personnes pendant 24 heures. Le maintien durable d’une petite population reste possible avec une infrastructure entretenue et les consommables nécessaires.","texte_reference":"En une heure, aménagez avec des ressources réelles un refuge compatible pour cinq personnes pendant 24 heures. Le maintien durable d’une petite population reste possible avec une infrastructure entretenue et les consommables nécessaires.","lore":"Une infrastructure imparfaite peut devenir un milieu vivable si l’on comprend exactement ce que l’espèce exige. La Ligue baséanne assemble air, température, humidité et ressources en un habitat minimal capable de durer.","groupe_actuel":"Organisations Extrals › Croix Verte / Ligue Baséanne — 16 PTV › Acclimatation artificielle — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_croix_verte_intervention_xenobi', 'Croix Verte — Intervention xénobiologique', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-pont-metabolique', 'Pont métabolique', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"","texte_court":"Adapter un traitement, nutriment ou support biologique connu afin qu’un organisme d’une autre espèce puisse l’utiliser sans incompatibilité fondamentale","texte_reference":"Adapter un traitement, nutriment ou support biologique connu afin qu’un organisme d’une autre espèce puisse l’utiliser sans incompatibilité fondamentale","lore":"La Ligue baséanne construit une compatibilité provisoire entre organisme et ressource. Aliment, médicament ou support biologique est reformulé jusqu’à devenir assimilable par une physiologie qui l’aurait normalement rejeté.","groupe_actuel":"Organisations Extrals › Croix Verte / Ligue Baséanne — 16 PTV › Intervention xénobiologique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-conversion-therapeutique', 'Conversion thérapeutique', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"Préparation — dix minutes","texte_court":"Après étude de la pathologie et adaptation réelle d’un traitement disponible, la cible reçoit un nouveau test de résistance à +3 contre l’affection traitée. Dix minutes de préparation ; aucun traitement universel, résurrection ou disparition des dégâts déjà subis.","texte_reference":"Après étude de la pathologie et adaptation réelle d’un traitement disponible, la cible reçoit un nouveau test de résistance à +3 contre l’affection traitée. Dix minutes de préparation ; aucun traitement universel, résurrection ou disparition des dégâts déjà subis.","lore":"Un traitement n’est utile que s’il parle la langue du corps qui le reçoit. Le spécialiste traduit dosage, vecteur et métabolisme d’une physiologie connue vers une autre sans prétendre que deux espèces sont chimiquement identiques.","groupe_actuel":"Organisations Extrals › Croix Verte / Ligue Baséanne — 16 PTV › Intervention xénobiologique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-stabilisation-exotique', 'Stabilisation exotique', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"","activation":"Voir règle détaillée","texte_court":"Tentez la Stabilisation d’une physiologie inconnue avec +3, à partir des signes vitaux réellement observables. Les moyens de soin doivent être disponibles et une destruction vitale définitive reste irréversible.","texte_reference":"Tentez la Stabilisation d’une physiologie inconnue avec +3, à partir des signes vitaux réellement observables. Les moyens de soin doivent être disponibles et une destruction vitale définitive reste irréversible.","lore":"Face à une espèce inconnue, le xénobiologiste cherche d’abord ce qui est universel : circulation, échange, pression, intégrité. Il stabilise la fonction vitale avant de prétendre comprendre l’anatomie entière.","groupe_actuel":"Organisations Extrals › Croix Verte / Ligue Baséanne — 16 PTV › Intervention xénobiologique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-support-vital-universel', 'Support vital universel', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"","activation":"Actif — 2 PA","texte_court":"Avec un matériel adapté disponible, consacrez 2 PA à établir un maintien vital d’urgence d’une physiologie inconnue pendant 24 heures maximum. Les consommables restent requis, aucune guérison ou résurrection n’est donnée et une destruction vitale définitive reste fatale.","texte_reference":"Avec un matériel adapté disponible, consacrez 2 PA à établir un maintien vital d’urgence d’une physiologie inconnue pendant 24 heures maximum. Les consommables restent requis, aucune guérison ou résurrection n’est donnée et une destruction vitale définitive reste fatale.","lore":"Quand aucun protocole n’existe encore, la Croix Verte fabrique un maintien de vie à partir de principes fondamentaux. L’objectif n’est pas de guérir l’inconnu, seulement de lui acheter le temps nécessaire pour qu’un vrai traitement soit trouvé.","groupe_actuel":"Organisations Extrals › Croix Verte / Ligue Baséanne — 16 PTV › Intervention xénobiologique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_reptile', 'REPTILE', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-compartimentation-reptilienne', 'Compartimentation reptilienne', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"Voir règle détaillée","texte_court":"Les cellules réellement compartimentées imposent −3 aux tests d’enquête cherchant à remonter de l’une à l’autre. Une preuve directe conservée reste utilisable ; aucune identité parfaite ni preuve effacée.","texte_reference":"Les cellules réellement compartimentées imposent −3 aux tests d’enquête cherchant à remonter de l’une à l’autre. Une preuve directe conservée reste utilisable ; aucune identité parfaite ni preuve effacée.","lore":"REPTILE construit ses cellules comme des pièces qui n’ont pas besoin de connaître le plan complet. Une compromission locale révèle ce qui existe localement, pas une connexion imaginaire vers toutes les autres structures.","groupe_actuel":"Organisations Extrals › REPTILE — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-mandat-dormant', 'Mandat dormant', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"1/scène — accès antérieur réel","texte_court":"Une fois par scène, déclarez rétroactivement un ordre conditionnel plausible laissé lors d’un accès antérieur réel à une institution infiltrée. Il ne peut contredire un fait déjà établi, créer de l’autorité ou résoudre rétroactivement une action déjà accomplie.","texte_reference":"Une fois par scène, déclarez rétroactivement un ordre conditionnel plausible laissé lors d’un accès antérieur réel à une institution infiltrée. Il ne peut contredire un fait déjà établi, créer de l’autorité ou résoudre rétroactivement une action déjà accomplie.","lore":"Un ordre conditionnel bien placé peut dormir dans la procédure jusqu’au jour où son déclencheur survient. REPTILE s’appuie sur la légitimité apparente du système lui-même plutôt que sur une intervention de dernière minute.","groupe_actuel":"Organisations Extrals › REPTILE — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-decision-distribuee', 'Décision distribuée', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"","activation":"Voir règle détaillée","texte_court":"Lorsqu’un responsable devient indisponible, les relais effectivement briefés poursuivent l’opération et gagnent +3 aux tests de coordination directement nécessaires à sa continuité pendant la scène. Aucun agent, PA ou moyen supplémentaire n’est créé.","texte_reference":"Lorsqu’un responsable devient indisponible, les relais effectivement briefés poursuivent l’opération et gagnent +3 aux tests de coordination directement nécessaires à sa continuité pendant la scène. Aucun agent, PA ou moyen supplémentaire n’est créé.","lore":"Le réseau a déjà réparti responsabilités et seuils de décision avant que le centre tombe. Une opération préparée continue donc à vivre dans ses relais au lieu d’attendre qu’une seule personne lui redonne la permission d’exister.","groupe_actuel":"Organisations Extrals › REPTILE — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-le-systeme-agit', 'Le système agit', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Voir règle détaillée","texte_court":"1/Scénario, lorsqu’une institution réellement infiltrée dispose déjà de l’autorité, du personnel et des moyens nécessaires, le personnage peut faire déclencher une action importante préparée en amont sans devoir intervenir personnellement au moment critique. Le Talent ne crée jamais une autorité inexistante ni un pouvoir que l’institution ne possède pas","texte_reference":"1/Scénario, lorsqu’une institution réellement infiltrée dispose déjà de l’autorité, du personnel et des moyens nécessaires, le personnage peut faire déclencher une action importante préparée en amont sans devoir intervenir personnellement au moment critique. Le Talent ne crée jamais une autorité inexistante ni un pouvoir que l’institution ne possède pas","lore":"L’infiltration réussie devient réellement dangereuse lorsque l’institution peut agir sans la présence de l’infiltré. REPTILE déclenche alors un mécanisme administratif ou opérationnel déjà préparé et disposant de moyens authentiques.","groupe_actuel":"Organisations Extrals › REPTILE — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_mafia_shaediri_frontiere_noire', 'Mafia Shaediri — Frontière noire', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-transpondeur-fantome', 'Transpondeur fantôme', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"","texte_court":"Préparer une signature ou identification de transit cohérente pour tromper les contrôles routiniers d’un trajet local, tant qu’aucune enquête ciblée ne dispose d’un élément compromettant","texte_reference":"Préparer une signature ou identification de transit cohérente pour tromper les contrôles routiniers d’un trajet local, tant qu’aucune enquête ciblée ne dispose d’un élément compromettant","lore":"Un transit clandestin est plus crédible lorsqu’il ressemble à quelque chose qui devrait vraiment être là. Le faux transpondeur reprend les codes et habitudes du trafic local jusqu’au moment où une enquête possède enfin une raison précise de douter.","groupe_actuel":"Organisations Extrals › Mafia Shaediri — 23 PTV › Frontière noire — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-soute-aveugle', 'Soute aveugle', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"","texte_court":"Avec un véhicule ou local réellement modifiable, créer une zone dissimulée conçue pour échapper aux inspections et scans de routine. Un contrôle ciblé ou une technologie explicitement adaptée peut toujours la trouver","texte_reference":"Avec un véhicule ou local réellement modifiable, créer une zone dissimulée conçue pour échapper aux inspections et scans de routine. Un contrôle ciblé ou une technologie explicitement adaptée peut toujours la trouver","lore":"La soute aveugle est pensée contre l’inspection routinière : volumes morts, blindage et accès détourné. Elle n’est pas magique ; une recherche ciblée ou un scanner conçu pour ce type de cache peut toujours la débusquer.","groupe_actuel":"Organisations Extrals › Mafia Shaediri — 23 PTV › Frontière noire — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-fenetre-orbitale', 'Fenêtre de transit', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"","activation":"Repérage et préparation du transit","texte_court":"Identifiez un créneau réel de surveillance, de trafic ou de synchronisation pour un transit clandestin terrestre, portuaire, aérien ou orbital : +3 au premier test qui l’exploite. Ni véhicule, autorisation ni invisibilité ne sont fournis.","texte_reference":"Identifiez un créneau réel de surveillance, de trafic ou de synchronisation pour un transit clandestin terrestre, portuaire, aérien ou orbital : +3 au premier test qui l’exploite. Ni véhicule, autorisation ni invisibilité ne sont fournis.\n\nNom proposé : « Fenêtre de transit », identifiant historique conservé.","lore":"La Frontière noire vit dans les moments où les réseaux de surveillance ne regardent pas au même endroit. Le Shaediri identifie ces fenêtres réelles et y fait passer appareil ou cargaison sans inventer d’invisibilité.","groupe_actuel":"Organisations Extrals › Mafia Shaediri — 23 PTV › Frontière noire — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-route-cislunaire', 'Route cislunaire', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"","activation":"","texte_court":"Avec accès au réseau et aux moyens de transport réels, construire une route clandestine cohérente Terre ↔ orbite ↔ Lune utilisant relais, fenêtres et nœuds locaux. Le Talent n’ouvre pas une route galactique gratuite","texte_reference":"Avec accès au réseau et aux moyens de transport réels, construire une route clandestine cohérente Terre ↔ orbite ↔ Lune utilisant relais, fenêtres et nœuds locaux. Le Talent n’ouvre pas une route galactique gratuite","lore":"Une route clandestine Terre-orbite-Lune est faite de relais, de créneaux et de gens qui ferment les yeux. Le réseau Shaediri sait assembler ces fragments en trajet cohérent sans transformer la contrebande locale en portail galactique.","groupe_actuel":"Organisations Extrals › Mafia Shaediri — 23 PTV › Frontière noire — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_mafia_shaediri_marche_xeno', 'Mafia Shaediri — Marché xéno', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-substitution-galactique', 'Substitution galactique', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"","texte_court":"Identifier dans le marché xéno une alternative fonctionnelle à un composant ou produit rare lorsque l’original est indisponible. Il faut encore trouver et payer l’objet","texte_reference":"Identifier dans le marché xéno une alternative fonctionnelle à un composant ou produit rare lorsque l’original est indisponible. Il faut encore trouver et payer l’objet","lore":"Le marché xéno contient souvent plusieurs technologies répondant au même besoin. Le Shaediri sait chercher l’alternative fonctionnelle quand le composant exact manque, à condition que quelqu’un la vende encore et que le personnage puisse la payer.","groupe_actuel":"Organisations Extrals › Mafia Shaediri — 23 PTV › Marché xéno — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-provenance-brouillee', 'Provenance brouillée', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"Voir règle détaillée","texte_court":"Une acquisition réellement passée par les relais appropriés impose −3 aux tests visant à en reconstituer la provenance. Les preuves directes subsistent et les transferts ont des délais et coûts réels.","texte_reference":"Une acquisition réellement passée par les relais appropriés impose −3 aux tests visant à en reconstituer la provenance. Les preuves directes subsistent et les transferts ont des délais et coûts réels.","lore":"Chaque intermédiaire change un détail de l’histoire de l’objet : facture, transporteur, entrepôt, propriétaire. À la fin, la provenance devient difficile à lire d’un coup, mais aucune preuve concrète n’est effacée par principe.","groupe_actuel":"Organisations Extrals › Mafia Shaediri — 23 PTV › Marché xéno — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-chaine-interdite', 'Chaîne interdite', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"","activation":"","texte_court":"Utiliser les filières existantes pour sourcer un bien contrôlé ou interdit non unique. La disponibilité, le prix, les délais et les risques restent réels","texte_reference":"Utiliser les filières existantes pour sourcer un bien contrôlé ou interdit non unique. La disponibilité, le prix, les délais et les risques restent réels","lore":"La Mafia Shaediri connaît les mains qui acceptent de vendre ce qui ne devrait pas circuler. Le réseau ouvre l’accès au bien interdit, mais ne fait disparaître ni prix, délai, rareté ni risque.","groupe_actuel":"Organisations Extrals › Mafia Shaediri — 23 PTV › Marché xéno — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-importation-noire', 'Importation noire', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"","activation":"Voir règle détaillée","texte_court":"Après vérification d’un bien rare non unique réellement disponible dans le réseau, obtenez un prix et un délai de livraison dans la zone de campagne. L’engagement de la filière est réel dans ces conditions, sauf obstacle nouveau effectivement joué ; l’objet reste payant.","texte_reference":"Après vérification d’un bien rare non unique réellement disponible dans le réseau, obtenez un prix et un délai de livraison dans la zone de campagne. L’engagement de la filière est réel dans ces conditions, sauf obstacle nouveau effectivement joué ; l’objet reste payant.","lore":"Une filière noire peut faire voyager un objet rare de relais en relais jusqu’à la campagne. Ce qui arrive est bien réel, acheté quelque part, et reste soumis à toutes les difficultés qu’implique son transport clandestin.","groupe_actuel":"Organisations Extrals › Mafia Shaediri — 23 PTV › Marché xéno — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_mafia_shaediri_shaekori', 'Mafia Shaediri — Shaekori', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-refuge-fraternel', 'Refuge fraternel', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"","texte_court":"Dans une zone où un réseau Shaekori existe réellement, trouver un refuge clandestin difficile à relier au personnage sans piste concrète","texte_reference":"Dans une zone où un réseau Shaekori existe réellement, trouver un refuge clandestin difficile à relier au personnage sans piste concrète","lore":"Une ville où vit la Fraternité contient aussi ses portes discrètes. Le membre sait quel appartement, atelier ou arrière-salle peut devenir refuge sans que le lieu soit automatiquement relié à lui par les contrôles ordinaires.","groupe_actuel":"Organisations Extrals › Mafia Shaediri — 23 PTV › Shaekori — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-relais-brule', 'Relais brûlé', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"1/scène — avant interception","texte_court":"Une fois par scène, lorsqu’un relais vient d’être compromis, détournez avant interception une opération encore en cours vers une solution alternative réellement praticable. Pas d’annulation d’une arrestation ou saisie déjà résolue, ni disparition des preuves.","texte_reference":"Une fois par scène, lorsqu’un relais vient d’être compromis, détournez avant interception une opération encore en cours vers une solution alternative réellement praticable. Pas d’annulation d’une arrestation ou saisie déjà résolue, ni disparition des preuves.","lore":"Un relais compromis est parfois moins précieux que les liens qu’il protège. Les Shaekori savent l’abandonner proprement, couper ses connexions et faire basculer l’opération vers une voie préparée avant que l’incendie ne gagne le réseau.","groupe_actuel":"Organisations Extrals › Mafia Shaediri — 23 PTV › Shaekori — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-extraction-fraternelle', 'Extraction fraternelle', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"","activation":"","texte_court":"1/Scénario, avec un réseau local réel et une voie praticable, organiser l’extraction d’un membre ou allié depuis une position dangereuse mais non totalement verrouillée. Cela prend le temps nécessaire et n’invoque pas une équipe depuis le néant","texte_reference":"1/Scénario, avec un réseau local réel et une voie praticable, organiser l’extraction d’un membre ou allié depuis une position dangereuse mais non totalement verrouillée. Cela prend le temps nécessaire et n’invoque pas une équipe depuis le néant","lore":"Les Shaekori ne laissent pas facilement un des leurs enfermé derrière eux. Si un réseau local possède réellement une voie de sortie, il peut organiser l’extraction avec les personnes et les moyens déjà présents dans la zone.","groupe_actuel":"Organisations Extrals › Mafia Shaediri — 23 PTV › Shaekori — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-reseau-sans-centre', 'Réseau sans centre', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"c","acces":"V/SR/R","activation":"Préparation — une journée","texte_court":"Après la perte d’un relais, rétablissez en une journée une fonction locale de la filière à partir de contacts et moyens restés intacts. Cela ne libère pas les captifs, ne remplace pas le matériel perdu et ne recrée pas une organisation entièrement détruite.","texte_reference":"Après la perte d’un relais, rétablissez en une journée une fonction locale de la filière à partir de contacts et moyens restés intacts. Cela ne libère pas les captifs, ne remplace pas le matériel perdu et ne recrée pas une organisation entièrement détruite.","lore":"La Fraternité refuse le point unique dont dépendraient tous les autres. Chaque relais connaît assez peu du reste pour que la chute d’un nœud important oblige encore l’adversaire à reconstruire toute la cartographie.","groupe_actuel":"Organisations Extrals › Mafia Shaediri — 23 PTV › Shaekori — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_hydroguard_combat_hydrostatique', 'Hydroguard — Combat hydrostatique', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-equilibrage-brutal', 'Équilibrage brutal', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"","texte_court":"Les turbulences, changements de courant ou pertes d’orientation dans un milieu liquide ne suffisent pas à interrompre une action physique que le personnage peut réellement accomplir","texte_reference":"Les turbulences, changements de courant ou pertes d’orientation dans un milieu liquide ne suffisent pas à interrompre une action physique que le personnage peut réellement accomplir","lore":"Courants et remous déplacent l’environnement, pas la discipline du combattant. La Hydroguard sait conserver suffisamment d’orientation pour poursuivre l’action malgré les secousses ordinaires d’un milieu violent.","groupe_actuel":"Organisations Extrals › Hydroguard / THDF — 14 PTV › Combat hydrostatique — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-propulsion-vectorielle', 'Propulsion vectorielle', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"Passif — milieu liquide et propulsion adaptée","texte_court":"Avec la nage ou une propulsion appropriée, changez brutalement de direction sans perdre d’activation et ignorez jusqu’à −3 dus aux courants ou turbulences lors d’une manœuvre, attaque adaptée ou sauvetage aquatique. Les limites du corps et du dispositif restent applicables.","texte_reference":"Avec la nage ou une propulsion appropriée, changez brutalement de direction sans perdre d’activation et ignorez jusqu’à −3 dus aux courants ou turbulences lors d’une manœuvre, attaque adaptée ou sauvetage aquatique. Les limites du corps et du dispositif restent applicables.","lore":"Une propulsion maîtrisée permet de casser net une trajectoire aquatique. L’opérateur change d’axe, freine ou repart sans perdre de temps à remettre son corps dans un « haut » et un « bas » qui n’existent plus vraiment.","groupe_actuel":"Organisations Extrals › Hydroguard / THDF — 14 PTV › Combat hydrostatique — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-poussee-d-interception', 'Poussée d’interception', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"","activation":"Réaction — 1 PA — 1/round","texte_court":"Pour 1 PA en Réaction, une fois par round, parcourez jusqu’à votre Déplacement aquatique normal pour intercepter une menace physiquement accessible. Si vous atteignez un allié visé, le même PA inclut une Défense active physique d’interposition contre cette seule attaque.","texte_reference":"Pour 1 PA en Réaction, une fois par round, parcourez jusqu’à votre Déplacement aquatique normal pour intercepter une menace physiquement accessible. Si vous atteignez un allié visé, le même PA inclut une Défense active physique d’interposition contre cette seule attaque.","lore":"Dans l’eau, l’interception se joue en trois dimensions. Le combattant hydrostatique lance son corps sur une courte trajectoire pour rejoindre, couvrir ou couper une menace avant que la distance ne se referme autrement.","groupe_actuel":"Organisations Extrals › Hydroguard / THDF — 14 PTV › Combat hydrostatique — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-percee-hydrostatique', 'Percée hydrostatique', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"c","acces":"","activation":"1/scène — Déplacement normalement payé","texte_court":"Une fois par scène, lors d’un Déplacement aquatique normalement payé, franchissez un courant violent, une turbulence ou un obstacle de milieu normalement capable de vous arrêter, en entraînant une personne remorquée si votre capacité le permet. Une impossibilité physique absolue reste impossible.","texte_reference":"Une fois par scène, lors d’un Déplacement aquatique normalement payé, franchissez un courant violent, une turbulence ou un obstacle de milieu normalement capable de vous arrêter, en entraînant une personne remorquée si votre capacité le permet. Une impossibilité physique absolue reste impossible.","lore":"La Hydroguard apprend à lire le courant comme un terrain qui se traverse, non comme un mur. Une poussée bien choisie permet de franchir turbulence et pression sans que le milieu impose automatiquement l’arrêt.","groupe_actuel":"Organisations Extrals › Hydroguard / THDF — 14 PTV › Combat hydrostatique — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_hydroguard_sauvetage_abyssal', 'Hydroguard — Sauvetage abyssal', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-remorquage-de-combat', 'Remorquage de combat', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"","texte_court":"Dans l’eau, déplacer une cible inconsciente ou consentante de gabarit comparable sans que le remorquage réduise à lui seul le Déplacement normal","texte_reference":"Dans l’eau, déplacer une cible inconsciente ou consentante de gabarit comparable sans que le remorquage réduise à lui seul le Déplacement normal","lore":"Dans l’eau, un corps neutralisé n’a pas à devenir une ancre. L’entraînement THDF apprend à le placer dans le flux du déplacement pour que le sauvetage conserve l’allure normale du nageur.","groupe_actuel":"Organisations Extrals › Hydroguard / THDF — 14 PTV › Sauvetage abyssal — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-partage-de-survie', 'Partage de survie', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"","activation":"Action de partage — matériel compatible","texte_court":"Avec une réserve, un recycleur ou une physiologie compatible, partagez temporairement le support vital d’une cible adjacente sans perdre votre propre usage. Les deux consommations sont décomptées ; aucune réserve supplémentaire n’apparaît.","texte_reference":"Avec une réserve, un recycleur ou une physiologie compatible, partagez temporairement le support vital d’une cible adjacente sans perdre votre propre usage. Les deux consommations sont décomptées ; aucune réserve supplémentaire n’apparaît.","lore":"Une réserve vitale bien comprise peut nourrir deux organismes au lieu d’un seul. Le sauveteur partage air ou support sans condamner immédiatement son propre système, tant que leur physiologie et le dispositif l’acceptent réellement.","groupe_actuel":"Organisations Extrals › Hydroguard / THDF — 14 PTV › Sauvetage abyssal — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-sas-humain', 'Sas humain', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"Voir règle détaillée","texte_court":"Avec les équipements adaptés et quelques instants de préparation, accompagnez une cible dans une transition de milieu normalement exigeante sans sas complet. Le protocole fixe avant l’action pression, température, durée et limites supportées ; les transitions physiquement mortelles ne sont pas annulées.","texte_reference":"Avec les équipements adaptés et quelques instants de préparation, accompagnez une cible dans une transition de milieu normalement exigeante sans sas complet. Le protocole fixe avant l’action pression, température, durée et limites supportées ; les transitions physiquement mortelles ne sont pas annulées.","lore":"Avec équipement et quelques secondes de discipline, le sauveteur remplace une partie du travail d’un sas complet. Il accompagne le corps à travers pression, température ou changement de milieu sans prétendre rendre survivable ce qui ne l’est pas.","groupe_actuel":"Organisations Extrals › Hydroguard / THDF — 14 PTV › Sauvetage abyssal — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-extraction-abyssale', 'Extraction abyssale', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Actif — 1 PA — 1/scène","texte_court":"Pour 1 PA, une fois par scène, saisissez une victime neutralisée à votre portée puis remorquez-la jusqu’à votre Déplacement aquatique normal en franchissant un obstacle de milieu réellement franchissable. Équipements, voie de sortie et survie biologique restent nécessaires.","texte_reference":"Pour 1 PA, une fois par scène, saisissez une victime neutralisée à votre portée puis remorquez-la jusqu’à votre Déplacement aquatique normal en franchissant un obstacle de milieu réellement franchissable. Équipements, voie de sortie et survie biologique restent nécessaires.","lore":"Le sauvetage abyssal ne sépare pas saisir, franchir et remorquer. L’opérateur transforme ces gestes en une seule séquence d’extraction, tant que matériel, voie et survie physique rendent encore la manœuvre possible.","groupe_actuel":"Organisations Extrals › Hydroguard / THDF — 14 PTV › Sauvetage abyssal — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_smrc_agi_expression_mosaique', 'SMRC / AGI — Expression mosaïque', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-veille-genetique', 'Veille génétique', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"Réaction — 1/scène","texte_court":"Reconnaissez le greffon en défaut et, une fois par scène, mettez-le volontairement au repos avant qu’un dysfonctionnement détecté n’entraîne une complication secondaire. Sa fonction est alors indisponible ; une lésion déjà infligée n’est pas effacée.","texte_reference":"Reconnaissez le greffon en défaut et, une fois par scène, mettez-le volontairement au repos avant qu’un dysfonctionnement détecté n’entraîne une complication secondaire. Sa fonction est alors indisponible ; une lésion déjà infligée n’est pas effacée.","lore":"Les conflits entre greffes ont des signes subtils avant de devenir catastrophes. Le porteur entraîné reconnaît quelle modification commence à rejeter, dériver ou perturber l’organisme avant même d’en connaître toute la cause.","groupe_actuel":"Organisations Extrals › SMRC / AGI — Orgienétique — 14 PTV › Expression mosaïque — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-profil-phenotypique', 'Profil phénotypique', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"Actif — 1 PA","texte_court":"Pour 1 PA, recalibrez une modification biologique compatible vers une expression alternative définie avant achat qui demanderait normalement une intervention technique. Les modes ordinaires de l’équipement restent utilisables sans le talent ; aucune fonction absente n’est inventée.","texte_reference":"Pour 1 PA, recalibrez une modification biologique compatible vers une expression alternative définie avant achat qui demanderait normalement une intervention technique. Les modes ordinaires de l’équipement restent utilisables sans le talent ; aucune fonction absente n’est inventée.","lore":"Une même modification peut contenir plusieurs expressions prévues. Le porteur apprend à passer d’un profil à l’autre comme il changerait l’état d’un organe spécialisé, sans chirurgie supplémentaire.","groupe_actuel":"Organisations Extrals › SMRC / AGI — Orgienétique — 14 PTV › Expression mosaïque — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-sursaut-d-expression', 'Sursaut d’expression', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"","activation":"1/scène — selon les coûts du greffon","texte_court":"Une fois par scène, activez le sur-régime compatible selon ses coûts normaux et gagnez +3 au premier test qui en exploite directement la fonction pendant le round. Les limites et conséquences réelles du greffon demeurent.","texte_reference":"Une fois par scène, activez le sur-régime compatible selon ses coûts normaux et gagnez +3 au premier test qui en exploite directement la fonction pendant le round. Les limites et conséquences réelles du greffon demeurent.","lore":"L’AGI sait pousser un greffon exactement dans le régime d’urgence prévu par ses concepteurs. Pendant quelques secondes, la fonction existante monte au-delà de sa norme sans inventer une capacité que la modification n’a jamais possédée.","groupe_actuel":"Organisations Extrals › SMRC / AGI — Orgienétique — 14 PTV › Expression mosaïque — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-heritage-recombine', 'Héritage recombiné', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"SR/R","activation":"Passif — greffe et talent spécifiques","texte_court":"Une greffe réellement possédée reproduisant le substrat biologique requis vous ouvre l’achat d’un talent racial extral précis, utilisable en R. Ce talent, ses prérequis et la greffe restent à acquérir ; aucun arbre entier ni essaim Homo Superior n’est accordé. Une fiche de greffe et un identifiant de talent autorisé sont nécessaires ; une description saisie par le joueur ne vaut pas autorisation du MJ.","texte_reference":"Une greffe réellement possédée reproduisant le substrat biologique requis vous ouvre l’achat d’un talent racial extral précis, utilisable en R. Ce talent, ses prérequis et la greffe restent à acquérir ; aucun arbre entier ni essaim Homo Superior n’est accordé.\n\nUne fiche de greffe et un identifiant de talent autorisé sont nécessaires ; une description saisie par le joueur ne vaut pas autorisation du MJ.","lore":"L’Expression mosaïque peut reconstruire assez fidèlement une architecture raciale pour en rendre certaines aptitudes accessibles. Le porteur n’hérite pas d’un peuple entier : seulement de ce que la greffe reproduit biologiquement de manière crédible.","groupe_actuel":"Organisations Extrals › SMRC / AGI — Orgienétique — 14 PTV › Expression mosaïque — 6 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_smrc_agi_architecture_organique', 'SMRC / AGI — Architecture organique', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-tolerance-au-greffon', 'Tolérance au greffon', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"Voir règle détaillée","texte_court":"Gagnez +3 aux tests pour résister à un rejet ou conflit biologique d’une greffe xéno compatible. Les incompatibilités fondamentales ne sont pas levées.","texte_reference":"Gagnez +3 aux tests pour résister à un rejet ou conflit biologique d’une greffe xéno compatible. Les incompatibilités fondamentales ne sont pas levées.","lore":"Le corps entraîné à l’orgienétique sait accueillir une biologie xéno compatible sans la traiter comme un ennemi par simple étrangeté. Une incompatibilité véritable reste pourtant une incompatibilité, quelle que soit la sophistication de l’intégration.","groupe_actuel":"Organisations Extrals › SMRC / AGI — Orgienétique — 14 PTV › Architecture organique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-redondance-biologique', 'Redondance biologique', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"1/scène — scène","texte_court":"Une fois par scène, maintenez pendant la scène la fonction d’une modification encore partiellement intacte malgré une Altération locale qui devrait la neutraliser. Ce contournement actif ne recrée pas les parties détruites et cesse avec la destruction de l’ensemble.","texte_reference":"Une fois par scène, maintenez pendant la scène la fonction d’une modification encore partiellement intacte malgré une Altération locale qui devrait la neutraliser. Ce contournement actif ne recrée pas les parties détruites et cesse avec la destruction de l’ensemble.","lore":"Une architecture vivante peut posséder son propre système de secours. Quand un élément local tombe, le doublon organique prend la fonction jusqu’à ce que la structure entière soit réellement compromise.","groupe_actuel":"Organisations Extrals › SMRC / AGI — Orgienétique — 14 PTV › Architecture organique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-compensation-croisee', 'Compensation croisée', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"","activation":"","texte_court":"1/Scène, une augmentation biologique compatible peut soutenir temporairement un autre système physiologique défaillant jusqu’à la fin de la scène, sans réparer la lésion elle-même","texte_reference":"1/Scène, une augmentation biologique compatible peut soutenir temporairement un autre système physiologique défaillant jusqu’à la fin de la scène, sans réparer la lésion elle-même","lore":"Une greffe peut parfois soutenir temporairement la fonction d’une autre partie du corps. L’AGI redirige alors capacité, circulation ou signal pour maintenir l’organisme jusqu’à la fin de la crise sans prétendre réparer la lésion.","groupe_actuel":"Organisations Extrals › SMRC / AGI — Orgienétique — 14 PTV › Architecture organique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-architecture-quadrigenique', 'Architecture quadrigénique', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Voir règle détaillée","texte_court":"Définissez un montage de deux à quatre greffes réellement possédées dont vous savez supprimer les interférences fonctionnelles corrigibles. Elles peuvent opérer ensemble sans ces interférences, mais conservent leurs coûts, fonctions, contraintes biologiques et Charge augmentique. Aucune réduction de Corruption, hausse d’Intégrité ou acquisition gratuite ; montage soumis à la compatibilité réelle et au MJ.","texte_reference":"Définissez un montage de deux à quatre greffes réellement possédées dont vous savez supprimer les interférences fonctionnelles corrigibles. Elles peuvent opérer ensemble sans ces interférences, mais conservent leurs coûts, fonctions, contraintes biologiques et Charge augmentique.\n\nAucune réduction de Corruption, hausse d’Intégrité ou acquisition gratuite ; montage soumis à la compatibilité réelle et au MJ.","lore":"L’orgienétique avancée ne juxtapose pas des greffes ; elle conçoit leurs interfaces. Plusieurs modifications étrangères peuvent donc partager le même organisme sans entrer automatiquement en guerre biologique lorsqu’elles ont été pensées pour coopérer.","groupe_actuel":"Organisations Extrals › SMRC / AGI — Orgienétique — 14 PTV › Architecture organique — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_emeraude_sanglante_armure_d_eme', 'Émeraude Sanglante — Armure d''Émeraude', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-mobilite-cuirassee', 'Mobilité cuirassée', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"Voir règle détaillée","texte_court":"Ignorez jusqu’à −3 de malus de mobilité dus à une armure réellement adaptée à votre morphologie. Les articulations bloquées, charges impossibles et contraintes physiques restent applicables.","texte_reference":"Ignorez jusqu’à −3 de malus de mobilité dus à une armure réellement adaptée à votre morphologie. Les articulations bloquées, charges impossibles et contraintes physiques restent applicables.","lore":"Les Talass de l’Émeraude ne considèrent pas l’armure lourde comme une boîte autour de leur cinétique. Un modèle correctement adapté préserve les articulations et vecteurs nécessaires à leurs bonds au lieu de les condamner à marcher comme des humanoïdes ordinaires.","groupe_actuel":"Organisations Extrals › Émeraude Sanglante — 16 PTV › Armure d’Émeraude — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-servomusculature', 'Servomusculature', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"Voir règle détaillée","texte_court":"Avec une armure assistée adaptée, gagnez +3 aux tests d’effort exploitant réellement sa servomusculature. Ce bonus améliore la maîtrise, sans relever les limites mécaniques, les PV ou les dégâts.","texte_reference":"Avec une armure assistée adaptée, gagnez +3 aux tests d’effort exploitant réellement sa servomusculature. Ce bonus améliore la maîtrise, sans relever les limites mécaniques, les PV ou les dégâts.","lore":"La servomusculature transforme une petite morphologie en opérateur d’armure lourde. Les moteurs portent une partie de l’effort et permettent des tâches de force qui resteraient impossibles au Talass nu.","groupe_actuel":"Organisations Extrals › Émeraude Sanglante — 16 PTV › Armure d’Émeraude — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-verrou-inertiel', 'Verrou inertiel', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"","activation":"Réaction — 1 PA — 1/round","texte_court":"Une fois par round, dépensez 1 PA en Réaction pour bloquer un renversement ou déplacement physique compatible avec les appuis et capacités de l’armure. Aucun arrêt de téléportation ou de force dépassant sa résistance réelle.","texte_reference":"Une fois par round, dépensez 1 PA en Réaction pour bloquer un renversement ou déplacement physique compatible avec les appuis et capacités de l’armure. Aucun arrêt de téléportation ou de force dépassant sa résistance réelle.","lore":"L’armure peut devenir ancre pendant une fraction de seconde. Joints, appuis et inertie se verrouillent ensemble pour refuser une poussée physique qui reste encore dans les capacités mécaniques du système.","groupe_actuel":"Organisations Extrals › Émeraude Sanglante — 16 PTV › Armure d’Émeraude — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-armure-obstinee', 'Armure obstinée', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"","activation":"Réaction — 1 PA — 1/scène","texte_court":"Pour 1 PA en Réaction, une fois par scène, isolez une panne non catastrophique et maintenez les fonctions essentielles d’une armure jusqu’à la fin de la scène. Une destruction réelle ne peut pas être ignorée.","texte_reference":"Pour 1 PA en Réaction, une fois par scène, isolez une panne non catastrophique et maintenez les fonctions essentielles d’une armure jusqu’à la fin de la scène. Une destruction réelle ne peut pas être ignorée.","lore":"Une Armure d’Émeraude est conçue pour continuer après la première panne. Le porteur sait isoler un défaut local et maintenir les fonctions essentielles jusqu’à la fin de l’engagement tant que la structure n’est pas réellement détruite.","groupe_actuel":"Organisations Extrals › Émeraude Sanglante — 16 PTV › Armure d’Émeraude — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_emeraude_sanglante_doctrine_du_', 'Émeraude Sanglante — Doctrine du Géant', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-sous-le-tir', 'Sous le tir', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"","activation":"Passif — approche sous le feu — 1/round","texte_court":"Une fois par round, la simple pression du feu ne suffit pas à interrompre votre approche d’un adversaire sensiblement plus massif ; +3 pour résister à la suppression ou intimidation de cette approche. Les impacts, blessures et obstacles matériels restent appliqués.","texte_reference":"Une fois par round, la simple pression du feu ne suffit pas à interrompre votre approche d’un adversaire sensiblement plus massif ; +3 pour résister à la suppression ou intimidation de cette approche. Les impacts, blessures et obstacles matériels restent appliqués.","lore":"Avancer sur plus massif que soi est une discipline de volonté autant que de trajectoire. La simple pression des tirs ne suffit pas à casser l’approche d’un Talass formé, même si chaque impact réel continue évidemment de compter.","groupe_actuel":"Organisations Extrals › Émeraude Sanglante — 16 PTV › Doctrine du Géant — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-ouvrir-la-cuirasse', 'Ouvrir la cuirasse', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"","activation":"Voir règle détaillée","texte_court":"Lorsqu’une attaque produit une Altération appropriée, remplacez-la par une brèche qui diminue de 2 l’Armure matérielle de la zone atteinte pour la scène ou jusqu’à réparation. Une même zone ne cumule pas plusieurs réductions de ce talent, et une attaque doit réellement pouvoir endommager la protection.","texte_reference":"Lorsqu’une attaque produit une Altération appropriée, remplacez-la par une brèche qui diminue de 2 l’Armure matérielle de la zone atteinte pour la scène ou jusqu’à réparation. Une même zone ne cumule pas plusieurs réductions de ce talent, et une attaque doit réellement pouvoir endommager la protection.","lore":"Quand une attaque réussie offre le choix d’une conséquence, la Doctrine du Géant préfère parfois la chirurgie au spectaculaire. Elle transforme l’impact en défaut exploitable dans la cuirasse plutôt qu’en autre effet immédiat.","groupe_actuel":"Organisations Extrals › Émeraude Sanglante — 16 PTV › Doctrine du Géant — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-exploiter-la-breche', 'Exploiter la brèche', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"","activation":"","texte_court":"Une fois par round, lorsqu’une cible possède une brèche créée ou identifiée par la Doctrine du Géant, une attaque du personnage visant explicitement cette brèche réduit de 2 l’Armure applicable","texte_reference":"Une fois par round, lorsqu’une cible possède une brèche créée ou identifiée par la Doctrine du Géant, une attaque du personnage visant explicitement cette brèche réduit de 2 l’Armure applicable","lore":"Une protection déjà ouverte n’a pas besoin d’être vaincue une seconde fois. L’Émeraude Sanglante dirige son attaque dans la faiblesse existante et fait travailler le coup contre ce qui reste derrière plutôt que contre toute l’armure.","groupe_actuel":"Organisations Extrals › Émeraude Sanglante — 16 PTV › Doctrine du Géant — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-demantelement-methodique', 'Démantèlement méthodique', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Actif — 1 PA — 1/scène","texte_court":"Pour 1 PA, une fois par scène, désignez une brèche réelle d’une cible plus massive : jusqu’à trois alliés capables de la viser ignorent 2 Armure sur leur première attaque contre elle de chaque round pendant la scène. Ce bénéfice remplace un Exploiter la brèche équivalent, sans seconde attaque ni ligne de tir créée.","texte_reference":"Pour 1 PA, une fois par scène, désignez une brèche réelle d’une cible plus massive : jusqu’à trois alliés capables de la viser ignorent 2 Armure sur leur première attaque contre elle de chaque round pendant la scène. Ce bénéfice remplace un Exploiter la brèche équivalent, sans seconde attaque ni ligne de tir créée.","lore":"La Doctrine du Géant apprend à ne pas perdre une brèche dès qu’elle est créée. Le premier combattant la maintient lisible pour l’escouade afin que plusieurs alliés puissent viser le même défaut avant que la cible ne se réorganise.","groupe_actuel":"Organisations Extrals › Émeraude Sanglante — 16 PTV › Doctrine du Géant — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_aidh_doctrine_d_intervention', 'AIDH — Doctrine d''Intervention', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-coordination-de-continuite', 'Coordination de Continuité', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1 PA","texte_court":"Le personnage peut fournir l’Assistance normale +2 en combat sur un test non offensif d’un allié malgré l’interdiction générale de l’assistance de combat. Il doit posséder la Compétence pertinente à 1+, être réellement en mesure d’aider et dépenser 1 PA. Jamais sur une Attaque, une Défense active ou un pouvoir strictement personnel.","texte_reference":"Le personnage peut fournir l’Assistance normale +2 en combat sur un test non offensif d’un allié malgré l’interdiction générale de l’assistance de combat. Il doit posséder la Compétence pertinente à 1+, être réellement en mesure d’aider et dépenser 1 PA. Jamais sur une Attaque, une Défense active ou un pouvoir strictement personnel.","lore":"Les Protocoles de Continuité apprennent à aider sans casser le rythme du combat. Un opérateur compétent peut consacrer une part de son attention à l’action technique d’un allié et réellement améliorer son exécution.","groupe_actuel":"Protocoles de Continuité — 7 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-releve-de-position', 'Relève de position', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/round","texte_court":"Au début d’une passe, avant que l’un des deux ait agi dans cette passe, le personnage et un allié consentant disposant chacun d’au moins 1 PA peuvent échanger leur position dans l’ordre d’Initiative pour cette passe uniquement. Ils doivent pouvoir communiquer et participer à la même action tactique. Aucun PA n’est créé.","texte_reference":"Au début d’une passe, avant que l’un des deux ait agi dans cette passe, le personnage et un allié consentant disposant chacun d’au moins 1 PA peuvent échanger leur position dans l’ordre d’Initiative pour cette passe uniquement. Ils doivent pouvoir communiquer et participer à la même action tactique. Aucun PA n’est créé.","lore":"La doctrine d’intervention traite l’initiative comme une ressource d’équipe. Deux agents préparés peuvent échanger leur place dans la séquence afin que celui dont la fonction est devenue urgente agisse au bon moment.","groupe_actuel":"Doctrines AIDH › Doctrine d’Intervention AIDH — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-interposition-doctrinale', 'Interposition doctrinale', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Réaction — 1 PA — 1/round","texte_court":"Quand un allié proche est ciblé par une attaque que le personnage perçoit et contre laquelle il peut physiquement intervenir, celui-ci effectue Agilité + Esquive + 1d10e. L’attaque doit dépasser la meilleure Défense entre celle de la cible et celle obtenue par l’intervenant. La fiction détermine s’il dévie, tire l’allié ou s’interpose ; aucune impossibilité physique n’est créée.","texte_reference":"Quand un allié proche est ciblé par une attaque que le personnage perçoit et contre laquelle il peut physiquement intervenir, celui-ci effectue Agilité + Esquive + 1d10e. L’attaque doit dépasser la meilleure Défense entre celle de la cible et celle obtenue par l’intervenant. La fiction détermine s’il dévie, tire l’allié ou s’interpose ; aucune impossibilité physique n’est créée.","lore":"L’AIDH entraîne ses opérateurs à lire une attaque comme un problème de trajectoire. Tirer un allié, dévier ou prendre sa place devient un réflexe coordonné, sans jamais abolir les impossibilités physiques du terrain.","groupe_actuel":"Doctrines AIDH › Doctrine d’Intervention AIDH — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-releve-immediate', 'Relève immédiate', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"c","acces":"V/SR/R","activation":"Réaction — 1 PA — 1/round","texte_court":"Quand un allié visible tombe à 0 PV ou moins, est immobilisé, mis hors de combat ou perd brutalement sa capacité à tenir sa position, le personnage peut immédiatement effectuer un Déplacement vers lui. S’il termine au contact, il peut accomplir gratuitement une manipulation simple directement liée à sa sécurisation : le saisir, le tirer derrière un couvert adjacent, récupérer l’objet qu’il vient de lâcher ou prendre son relais sur un dispositif. Aucun soin ou attaque gratuit.","texte_reference":"Quand un allié visible tombe à 0 PV ou moins, est immobilisé, mis hors de combat ou perd brutalement sa capacité à tenir sa position, le personnage peut immédiatement effectuer un Déplacement vers lui. S’il termine au contact, il peut accomplir gratuitement une manipulation simple directement liée à sa sécurisation : le saisir, le tirer derrière un couvert adjacent, récupérer l’objet qu’il vient de lâcher ou prendre son relais sur un dispositif. Aucun soin ou attaque gratuit.","lore":"Quand un équipier tombe, l’AIDH considère la position vide comme une brèche à combler immédiatement. L’opérateur se déplace vers lui et accomplit le geste de sécurisation le plus simple avant que la scène ne se désorganise.","groupe_actuel":"Doctrines AIDH › Doctrine d’Intervention AIDH — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-sequence-coordonnee', 'Séquence coordonnée', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"1/scène — PA normaux dans chaque passe","texte_court":"Une fois par scène, coordonnez jusqu’à deux alliés et vous-même pour agir successivement dans les passes du round où chacun peut encore agir. Les PA restent normaux, une action par participant par passe, et aucun ordre d’Initiative n’est conservé au round suivant.","texte_reference":"Une fois par scène, coordonnez jusqu’à deux alliés et vous-même pour agir successivement dans les passes du round où chacun peut encore agir. Les PA restent normaux, une action par participant par passe, et aucun ordre d’Initiative n’est conservé au round suivant.","lore":"Deux agents qui partagent la même séquence tactique peuvent enchaîner leurs activations comme un seul mouvement collectif. Aucun temps n’est créé ; seule l’ordre des gestes devient volontairement synchronisé.","groupe_actuel":"Doctrines AIDH › Doctrine d’Intervention AIDH — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'extral', 'extral_organisations_de_verite_voies_hors_nature_aidh_protocoles_de_coherence_ex', 'AIDH — Protocoles de Cohérence (exigent un appareil de l''AIDH)', NULL, '{"nature":"extral","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-calibration-de-coherence', 'Calibration de cohérence', NULL, '{"nature":"extral","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Actif — 1 PA","texte_court":"Avec un capteur AIDH ou compatible, déterminer si l’Hologramme est activement sollicité dans une zone proche : fonctionnement normal, Révélation récente ou en cours, contrainte active sur le Voile, anomalie de cohérence ou stabilisation artificielle. Ne révèle pas la forme réelle d’une cible V et n’identifie pas automatiquement son espèce.","texte_reference":"Avec un capteur AIDH ou compatible, déterminer si l’Hologramme est activement sollicité dans une zone proche : fonctionnement normal, Révélation récente ou en cours, contrainte active sur le Voile, anomalie de cohérence ou stabilisation artificielle. Ne révèle pas la forme réelle d’une cible V et n’identifie pas automatiquement son espèce.","lore":"Un capteur AIDH ne voit pas la Vérité nue, mais il reconnaît quand l’Hologramme travaille. Révélation, contrainte, anomalie ou stabilisation artificielle laissent des signatures assez nettes pour être distinguées.","groupe_actuel":"Doctrines AIDH › Protocoles de Cohérence AIDH — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-chaine-invariante', 'Chaîne invariante', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"","texte_court":"Avec un dispositif d’Enregistrement invariant, relier pour le reste de la scène un unique flux ordinaire - caméra, micro, capteur, terminal ou transmission - de façon que toute modification ultérieure par l’Hologramme devienne détectable comme rupture d’intégrité. Cela ne rend pas les données absolument indestructibles.","texte_reference":"Avec un dispositif d’Enregistrement invariant, relier pour le reste de la scène un unique flux ordinaire - caméra, micro, capteur, terminal ou transmission - de façon que toute modification ultérieure par l’Hologramme devienne détectable comme rupture d’intégrité. Cela ne rend pas les données absolument indestructibles.","lore":"L’Enregistrement invariant protège moins l’image que son intégrité. Une fois le flux attaché à une chaîne de cohérence, toute réécriture ultérieure par l’Hologramme laisse une rupture détectable dans le dossier.","groupe_actuel":"Doctrines AIDH › Protocoles de Cohérence AIDH — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-ancrage-de-terrain', 'Ancrage de terrain', NULL, '{"nature":"extral","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Actif — 1 PA ; opposition en Réaction — 1 PA","texte_court":"Pour 1 PA et avec un dispositif AIDH approprié, ancrez une cible consentante à 10 m dans son état V/SR/R pour la scène, sans entretien. Pour 1 PA en Réaction face à un changement forcé, opposez Esprit + Technologie au jet adverse ; la cible peut toujours changer volontairement d’état. Le jet ajoute normalement 1d10e. Si l’effet adverse possède une procédure d’opposition spécifique, celle-ci prévaut ; aucune Révélation forcée et aucun cumul de protections équivalentes.","texte_reference":"Pour 1 PA et avec un dispositif AIDH approprié, ancrez une cible consentante à 10 m dans son état V/SR/R pour la scène, sans entretien. Pour 1 PA en Réaction face à un changement forcé, opposez Esprit + Technologie au jet adverse ; la cible peut toujours changer volontairement d’état.\n\nLe jet ajoute normalement 1d10e. Si l’effet adverse possède une procédure d’opposition spécifique, celle-ci prévaut ; aucune Révélation forcée et aucun cumul de protections équivalentes.","lore":"Les dispositifs AIDH de cohérence peuvent fixer une personne à l’état sous lequel le monde la traite déjà. L’ancrage ne révèle rien : il rend simplement plus difficile à une force extérieure d’imposer un changement de couche du Voile.","groupe_actuel":"Doctrines AIDH › Protocoles de Cohérence AIDH — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-fenetre-invariante', 'Fenêtre invariante', NULL, '{"nature":"extral","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Actif — 1 PA — scène","texte_court":"Pour 1 PA et avec le projecteur approprié, maintenez une zone d’observation stable jusqu’à la fin de la scène, dans son périmètre réel et avec un rayon maximal de 10 m. Elle protège l’observation et ses données, sans Révélation, vision de V cachée ou extinction de l’Hologramme.","texte_reference":"Pour 1 PA et avec le projecteur approprié, maintenez une zone d’observation stable jusqu’à la fin de la scène, dans son périmètre réel et avec un rayon maximal de 10 m. Elle protège l’observation et ses données, sans Révélation, vision de V cachée ou extinction de l’Hologramme.","lore":"La Fenêtre invariante crée un petit espace où l’instrumentation résiste quelques instants à la réinterprétation du Voile. Elle n’arrache personne à V ; elle permet seulement aux données correctement reliées de rester ce qu’elles ont réellement observé.","groupe_actuel":"Doctrines AIDH › Protocoles de Cohérence AIDH — 8 PTV","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'extral', 'extral-ventouses', 'Quadrimanie rocréenne (Ventouses)', NULL, '{"nature":"extral","cout":0,"cout_actuel":1,"palier":"trait","porte":null,"acces":"R","texte_court":null,"texte_reference":"Le mucus et les structures tentaculaires permettent au Rocréen de se fixer solidement aux surfaces. Il peut grimper sur des surfaces normalement très difficiles à saisir.","statut_regle":"correction","changements":"Ventouses devient le texte d''un trait gratuit (lot 09, −1 PTV)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
